class DatabricksSQLConfBase extends EdgeFlagSupport {
  def getEffectiveAutoCompressionRatio(config: HadoopConfiguration): Double = {
    val compressedCacheEnabled = config.get(IO_COMPRESSED_CACHE_ENABLED.key)
    // If IO_COMPRESSED_CACHE_ENABLED was set manually, we want to disable auto compression based
    // on compression ratio.
    if (compressedCacheEnabled != null) {
      if (Boolean.parseBoolean(compressedCacheEnabled)) return 0
      return Double.MaxValue
    }

    val instanceRatio = InstanceSpecificConf.getAutoCompressionRatio()
    val ratio = Option(config.getDouble(
      IO_CACHE_AUTO_COMPRESSION_RATIO.key,
      IO_CACHE_AUTO_COMPRESSION_RATIO.defaultValue.get)
    ).filter(_ >= 0.0)
    .getOrElse(instanceRatio)

    QueryPlanningTracker.get.foreach(_.recordEffectiveFeature(
      IO_CACHE_AUTO_COMPRESSION_RATIO.key, ratio != instanceRatio))
    return ratio
  }

  def getParquetCacheCrc(): Boolean = {
    SQLConf.get.getConfAndRecordEffectiveFeature(IO_CACHE_PARQUET_CRC)
  }

  /**
   * Whether the cluster is using the legacy "High Concurrency" configuration.
   *
   * This flag is false for all managed services including DBSQL, Serverless GC, and Serverless
   * Jobs.
   * Modern interactive compute and job clusters created through the UI are not considered
   * "High Concurrency" clusters. Currently active "High Concurrency" clusters are those created
   * before 2023 through the UI or using legacy API clients.
   *
   * To monitor active "High Concurrency" clusters, use this query in Logfood Master:
   * SELECT date, top_level_tags.cluster_creator_redacted, count(distinct top_level_tags.cluster_id)
   * FROM main.eng_lumberjack.prod_product_event_log_container_uptime_event
   * WHERE _partition_date >= date_sub(now(), 2)
   * AND event.cluster_resource_class_string = 'Serverless'
   * AND event.is_nephos is null
   * As of June 2025, approximately 100K legacy job clusters are launched daily.
   *
   * Note that this does NOT indicate whether Nephos is being used or not.
   * This function was originally named `isServerless()` because the "High Concurrency"
   * offering was originally branded as "Serverless" (even though it predated Nephos
   * and still ran in the customer's account).
   */
  def isLegacyHighConcurrency(): Boolean = {
    // Under testing environment, we can tolerant SparkEnv not initialized and just return false.
    // This is for ease of maintaining test cases.
    if ((DatabricksEdgeConfigs.testDefaultEnabled || Utils.isTesting) && SparkEnv.get == null) {
      return false
    } else {
      // scalastyle:off throwerror
      Option(SparkEnv.get).getOrElse(throw new AssertionError("SparkEnv not found"))
        .conf.get("spark.databricks.cluster.profile", "") == "serverless"
      // scalastyle:on throwerror
    }
  }

  /**
   * Make sure cpfs confs are not modified by the user
   *
   * @param key hadoop conf key
   */
  def requireNonCPFSHadoopConf(key: String): Unit = {
    if (key.startsWith("fs.cpfs-")) {
      throw new AnalysisException(
        errorClass = "_LEGACY_ERROR_TEMP_DBR_0228", messageParameters = Map("key" -> s"$key")
      )
    }
  }

  /**
   * Make sure fcfs confs are not modified by the user
   *
   * @param key hadoop conf key
   */
  def requireNonFCFSHadoopConf(key: String): Unit = {
    // TODO: remove the check after we default fcfs-sftp in universe
    if (key.startsWith("fs.fcfs-") && !key.startsWith("fs.fcfs-sftp")) {
      throw new AnalysisException(
        errorClass = "_LEGACY_ERROR_TEMP_DBR_0180",
        messageParameters = Map("key" -> s"$key")
      )
    }
  }

  /**
   * Make sure mcfs confs are not modified by the user
   *
   * @param key hadoop conf key
   */
  def requireNonMCFSHadoopConf(key: String): Unit = {
    if (key.startsWith("fs.mcfs-")) {
      throw new AnalysisException(s"Cannot change the conf for mcfs- filesystems: $key")
    }
  }

