        .doc(
          "When true, materializations are stored in the internal catalog/schema." +
          "spark.databricks.sql.materializationsInMVSchema must be false."
        )
        .booleanConf
        .createWithDefault(false)

    /**
     * Whether to register the top level entry for materialized view as views.
     */
    val REGISTER_MATERIALIZED_VIEW_AS_VIEW =
      buildConf("spark.databricks.sql.registerMaterializedViewAsView")
        .internal()
        .doc("When true, materialized views will be registered as views.")
        .booleanConf
        .createWithDefault(true)

    val MATERIALIZED_VIEW_WITH_SYNC_UPDATE_API =
      buildConf("spark.databricks.sql.MaterializedViewWithSyncUpdateAPI.enabled")
