  object Redshift {
    /**
     * Use an optimizer rule doing advanced query pushdown into Redshift.
     *
     * The rule is injected into extraOptimizations of the [[org.apache.spark.sql.SparkSession]]
     * the first time a RedshiftRelation is constructed.
     */
    val ADVANCED_PUSHDOWN = buildConf("spark.databricks.redshift.pushdown")
      .internal()
      .doc("When true, advanced query pushdown into Redshift is used.")
      .booleanConf
      .createWithDefault(true)

    val V2_FALLBACK = buildConf("spark.databricks.redshift.v2fallback")
      .internal()
      .doc("When true, on advanced query pushdown failure, v2 plan is going to be returned " +
        "instead of v1 plan")
      .booleanConf
      .createWithDefault(true)

    val USE_ROBUST_PUSHDOWN =
      buildConf("spark.databricks.redshift.robustProjectionPushdown")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("When true, failure to pushdown expression in Redshift pushdown rule won't cause" +
          " whole rule failure.")
        .booleanConf
        .createWithDefault(true)

    val SUPPORT_LOCAL_LIMIT_PUSHDOWN =
      buildConf("spark.databricks.redshift.supportLocalLimitPushdown")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("When true, local limit is pushed down to the Redshift if all the nodes " +
          "below it are able to be pushed down as well.")
        .booleanConf
        .createWithDefault(false)

    // TODO: SC-195121 cleanup
    val ASSERT_NO_LOGPATH_DRIVER_OPTION =
      buildConf("spark.databricks.redshift.assertNoLogPathDriverOption")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("If true, it is checked if connector options or URL contain logPath option. " +
          "Check is done only for bundled Redshift driver. " +
          "In case any of them do, query will fail. " +
          "If false, no check will be done.")
        .booleanConf
        .createWithDefault(true)

    // TODO: SC-202705 Clean up this flag
    val CUSTOM_PUSHDOWN_RULE_CAST_TO_DATE_ENABLED =
      buildConf("spark.databricks.redshift.customPushDownRuleCastToDateEnabled")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc(
          "If true, custom pushdown rule `RedshiftPushdown` handles CAST to DATE." +
          "This is important because projection expressions and join conditions " +
          "might contain CASTs, and those operations are not covered by standard DSv2 rule."
        )
        .booleanConf
        .createWithDefault(true)

    def isRobustRedshiftPushdownEnabled: Boolean =
      SQLConf.get.getConf(DatabricksSQLConf.Redshift.USE_ROBUST_PUSHDOWN)

    def supportLocalLimitPushdown: Boolean =
      SQLConf.get.getConf(SUPPORT_LOCAL_LIMIT_PUSHDOWN)

    def assertNoLogPathDriverOption: Boolean =
      SQLConf.get.getConf(ASSERT_NO_LOGPATH_DRIVER_OPTION)

    def customPushdownRuleCastToDateEnabled: Boolean =
      SQLConf.get.getConf(CUSTOM_PUSHDOWN_RULE_CAST_TO_DATE_ENABLED)
  } // End of Redshift

  object BigQuery {
