        .booleanConf
        .createWithDefault(true)

    val USE_STORAGE_API_FEDERATION_CONNECTOR =
      buildConf("spark.databricks.bigquery.useStorageApiFederationConnector")
        .internal()
        .doc("When true, a Storage API version of BigQuery connector is used for Federation.")
        .booleanConf
        .createWithDefault(true)

    val ENABLE_MATERIALIZATION =
      buildConf("spark.databricks.bigquery.enableMaterialization")
        .internal()
        .doc("When true, temporary tables will be materialized on BigQuery and read" +
          " through Storage API. This enables for better pushdown capabilities of BigQuery" +
          " connector and overall performance.")
        .owner("eng-lakehouse-federation")
        .booleanConf
        .createWithDefault(false)

    val PUSHDOWN_JOIN =
      buildConf("spark.databricks.bigquery.pushdownJoin")
        .internal()
        .doc("When true, pushdown of JOIN operator will be attempted for BigQuery connector.")
        .booleanConf
        .createWithDefault(true)

   val MATERIALIZATION_PER_REGION =
     buildConf("spark.databricks.bigquery.regionalMaterialization")
       .internal()
       .owner("eng-lakehouse-federation")
       .doc("When true, a materialization dataset will be" +
         " created for each region where data is read from.")
       .booleanConf
       .createWithDefault(true)

    val USER_CONTROLLED_MATERIALIZATION =
      buildConf("spark.databricks.bigquery.userControlledMaterialization")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("When true, a user can control matrialization on/off for each query" +
          " with SQL option 'enableMaterialization'.")
           .booleanConf
        .createWithDefault(true)

    val FIX_LOCAL_SORT_PUSHDOWN =
      buildConf("spark.databricks.connector.bigquery.fixLocalSortPushdown")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("Controls whether fix for local sort pushdown is enabled." +
            "With the fix enabled, the local sort operation is not pushed down." +
            "Without the fix, the operation is simply ignored causing issues with delta writer.")
        .booleanConf
        .createWithDefault(true)

    val LOAD_NAMESPACE_FALLBACK_ENABLED =
      buildConf("spark.databricks.connector.bigquery.loadNamespaceFallbackEnabled")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("Controls whether fallback for loading namespace is enabled for bigquery connector." +
          "Fallback mechanism uses different bigquery api, if initial API fails to provide result" +
          ".")
        .booleanConf
        .createWithDefault(false)

    val TABLE_CATALOG_ADDITIONAL_LOGGING_ENABLED =
      buildConf("spark.databricks.connector.bigquery.tableCatalogAdditionalLoggingEnabled")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("Controls whether additional logging for bigquery table catalog is enabled.")
        .booleanConf
        .createWithDefault(false)

    val SUPPORT_NESTED_FIELD_PUSHDOWN =
      buildConf("spark.databricks.connector.bigquery.supportNestedFieldPushdown")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("When true, nested fields are translatable by BigQuery dialect which allows pushing" +
          "them down when referenced in filters, aggregates, etc...")
        .booleanConf
        .createWithDefault(false)

    val ENABLE_GROUP_BY_COLUMN_ALIASING =
      buildConf("spark.databricks.bigquery.enableGroupByColumnAliasing")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("When true, enable aliasing of GROUP BY columns in V2ScanRelationPushdown rule.")
        .booleanConf
        .createWithDefault(true)

    val FULLY_QUALIFY_COLUMN_SAME_AS_TABLE =
      buildConf("spark.databricks.bigquery.fullyQualifyColumnSameAsTable")
        .internal()
        .owner("eng-lakehouse-federation")
        .doc("When true, columns with the same name as tables will be fully qualified to avoid" +
          " a known limitation of BQ (returning whole row struct instead of just one column).")
        .booleanConf
        .createWithDefault(true)

    def fixLocalSortPushDownEnabled: Boolean = SQLConf.get.getConf(FIX_LOCAL_SORT_PUSHDOWN)

    def loadNamespaceFallbackEnabled: Boolean = SQLConf.get.getConf(LOAD_NAMESPACE_FALLBACK_ENABLED)

    def tableCatalogAdditionalLoggingEnabled: Boolean =
      SQLConf.get.getConf(TABLE_CATALOG_ADDITIONAL_LOGGING_ENABLED)

    def supportNestedFieldPushdown: Boolean = SQLConf.get.getConf(SUPPORT_NESTED_FIELD_PUSHDOWN)

    def fullyQualifyColumnSameAsTable: Boolean =
      SQLConf.get.getConf(FULLY_QUALIFY_COLUMN_SAME_AS_TABLE)
  } // End of BigQuery

