  object SQLDW {
    /**
     * Use an optimizer rule doing advanced query pushdown into Azure SQL DW.
     *
     * The rule is injected into extraOptimizations of the [[org.apache.spark.sql.SparkSession]]
     * the first time a SqlDWRelation is constructed.
     */
    val ADVANCED_PUSHDOWN = buildConf("spark.databricks.sqldw.pushdown")
      .internal()
      .doc("When true, advanced query pushdown into Azure Synapse Analytics is used.")
      .booleanConf
      .createWithDefault(true)

    val TEMP_OBJECT_NAME_PREFIX = buildConf("spark.databricks.sqldw.tempObjectNamePrefix")
      .internal()
      .doc("Tag to be prepended to any temporary DW-side object created by this connector " +
        "(e.g. EXTERNAL TABLE, DATA SOURCE, FILE FORMAT, etc) in order to facilitate manual " +
        "cleanup of these objects in case they get leaked for some reason " +
        "(e.g. driver killed, bug, etc).")
      .stringConf
      .createWithDefault("tmp_databricks")

    val STREAMING_EXACTLY_ONCE = buildConf("spark.databricks.sqldw.streaming.exactlyOnce.enabled")
      .internal()
      .doc("When true, Azure Synapse Analytics streaming uses checkpoint table to ensure " +
        "exactly-once semantics, otherwise only at-least-once semantics are guaranteed")
      .booleanConf
      .createWithDefault(true)

    val STREAMING_CKPT_TABLE_PREFIX = buildConf(
      "spark.databricks.sqldw.streaming.exactlyOnce.checkpointTableNamePrefix")
      .internal()
      .doc(s"Tag to be prepended to the name of per-streaming-query checkpoint tables created by " +
        s"the connector, which are necessary to ensure exactly-once semantics. " +
        s"Unlike temp objects prefixed with ${TEMP_OBJECT_NAME_PREFIX.key}, these checkpoint " +
        s"tables have the same lifespan as the stream's 'checkpointLocation', so users are " +
        s"responsible for proper cleanup of them.")
      .stringConf
      .createWithDefault("databricks_streaming_checkpoint")

    val WRITE_SEMANTICS = buildConf(
      "spark.databricks.sqldw.writeSemantics")
      .internal()
      .doc("Write semantics for Azure Synapse Analytics connector. If the value is set " +
        "to \"polybase\", the connector will use PolyBase for batch and streaming writes; " +
        "if the value is set to \"copy\", the connector will use \"COPY INTO\" command." +
        " Otherwise, connector will decide the best value based on the Azure Synapse Analytics" +
        " database configuration.")
      .stringConf
      .createWithDefault("")

    val SYNAPSE_SERVICE_PRINCIPAL_CLIENT_ID = buildConf(
      "spark.databricks.sqldw.jdbc.service.principal.client.id")
      .internal()
      .doc("Client ID for accessing Azure Synapse Analytics using Oauth2.0 Service Principal " +
        s"authentication. This field is mandatory when Service Principal authentication option " +
        s"is enabled while writing the data frame into the Azure Synapse Analytics table.")
      .stringConf
      .createWithDefault("")

    val SYNAPSE_SERVICE_PRINCIPAL_CLIENT_SECRET = buildConf(
      "spark.databricks.sqldw.jdbc.service.principal.client.secret")
      .internal()
      .doc("Client Secret for accessing Azure Synapse Analytics using Oauth2.0 Service Principal " +
        s"authentication. This field is mandatory when Service Principal authentication option " +
        s"is enabled while writing the data frame into the Azure Synapse Analytics table.")
      .stringConf
      .createWithDefault("")

    val SQLDW_V2_ENABLED = buildConf("spark.databricks.sqldw.v2enabled")
      .internal()
      .doc("When true, on advanced query pushdown failure, v2 plan is going to be returned " +
        "instead of v1 plan")
      .owner("eng-sql-team-beg")
      .booleanConf
      .createWithDefault(true)

    val BYTE_TYPE_TO_SMALL_INT_MAPPING = buildConf(
      "spark.databricks.sqldw.byteTypeToSmallIntMapping")
      .internal()
      .doc("When true, maps spark's ByteType to SMALL_INT in order to avoid arithmetic " +
        "overflow errors in read/write path.")
      .owner("eng-lakehouse-federation")
      .booleanConf
      .createWithDefault(Utils.isTesting)
  } // End of SQLDW

  def isSqlDWV2Enabled: Boolean = {
    SQLConf.get.getConfString(DatabricksSQLConf.SQLDW.SQLDW_V2_ENABLED.key,
      DatabricksSQLConf.SQLDW.SQLDW_V2_ENABLED.defaultValueString).toBoolean
  }

  object Optimizer {

    val ALLOW_INDIRECT_MATERIALIZED_STAGES_FOR_RUNTIME_FILTERS =
      buildConf("spark.databricks.optimizer.allowIndirectMaterializedStagesForRuntimeFilters")
        .doc("When true, allow using indirect materialized stages from operators like Aggregate," +
          "Window, etc. as the build side of the bloom filter.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(false)

    // BEGIN stateful query engine configs
    val SQM_FORCED_METRICS_FOR_TESTING = buildConf(
      "spark.databricks.optimizer.sqm.forcedMetricsForTesting")
      .doc("Collection of forced metrics used for testing. These metrics will be stored into " +
        "the stateful query manager at captureMetrics() time, instead of the true metrics")
      .owner("eng-qo-team")
      .stringConf
      .toSequence
      .checkValue(v => v.forall(kv =>
        kv.split("=").length == 2 &&
          kv.split("=").last.toLong.isInstanceOf[Long]),
        "The parameters should be provided as a comma separated key=value pairs."
      )
      .createWithDefault(Seq())

    val ENABLE_STATEFUL_QUERY_MANAGER = buildConf(
      "spark.databricks.optimizer.sqm.enabled")
      .doc("Enable stateful query manager code path. This is a general flag that controls whether" +
        "metrics capture, processing, and directive serving is enabled. The individual use cases " +
        "are separately controlled by their own respective flags.")
      .owner("eng-qo-team")
      .booleanConf
      .createWithDefault(false)

    // Only works if ENABLE_STATEFUL_QUERY_MANAGER is enabled.
    val SQM_ENABLE_REGRESSION_DETECTION_FROM_STATS = buildConf(
      "spark.databricks.optimizer.sqm.regressionDetectionFromStats.enabled")
      .doc("Enable Regression Detection From Stats SQM use case.")
      .owner("eng-qo-team")
      .booleanConf
      .createWithDefault(false)

    val SQM_TRACING_ENABLED = buildConf(
      "spark.databricks.optimizer.sqm.tracing.enabled")
      .doc("If enabled, will allow detailed logging within the SQM module.")
      .owner("eng-qo-team")
      .booleanConf
      .createWithDefault(true)

    val SQM_REGRESSION_DETECTION_THRESHOLD = buildConf(
      "spark.databricks.execution.sqm.regressionDetectionThreshold")
      .doc("Threshold to be used by SQM regression detection use case when determining whether " +
        "a query execution regressed or not. Query will be marked as regressing if all metrics " +
        "of interest degrade at least by this threshold.")
      .owner("eng-qo-team")
      .doubleConf
      .createWithDefault(1.5)
    // END stateful query engine configs

    val DISABLE_NON_DETERMINISTIC_PRUNING_FILTERS =
      buildConf("spark.sql.optimizer.disableNonDeterministicPruningFilters")
        .internal()
        .doc("When true, if for the purpose of pruning filter injection, the subquery plan is " +
          "going to be duplicated, check whether the plan has any non-deterministic operators " +
          "or expressions. Disable the runtime filter injection if such an operator exists. " +
          "Refer ES-1366196 for more details.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val OPTIMIZE_CSV_JSON_EXPRS_USE_SCHEMA_FIELD_IN_PRUNED_STRUCT =
      buildConf("spark.sql.optimizer.optimizeCsvJsonExprs.useSchemaField")
        .internal()
        .doc("Use schema field name instead of the referenced field name for pruning structs")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val OPTIMIZER_FALLBACK_ON_EXCEPTION_ENABLED =
      buildConf("spark.sql.optimizer.fallback.onException.enabled")
        .internal()
        .doc("If enabled, the optimizer automatically mitigates and recovers from exception " +
          "failures from rules whose functionality is classified as optional, such as " +
          "performance related rewrites. Rules are individually marked as recoverable.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val OPTIMIZER_FALLBACK_ON_VALIDATION_ENABLED =
      buildConf("spark.sql.optimizer.fallback.onValidation.enabled")
        .internal()
        .doc("If enabled, the optimizer automatically validates protected rules, and " +
          "recovers from rules whose functionality is classified as optional, such as " +
          "performance related rewrites. Rules are individually marked as validated.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val OPTIMIZER_FALLBACK_ON_BATCH_EXCEPTION_ENABLED =
      buildConf("spark.sql.optimizer.fallback.onBatchException.enabled")
        .internal()
        .doc("If enabled, the optimizer automatically mitigates and recovers from exception " +
          "failures from batches whose functionality is classified as optional, such as " +
          "performance related rewrites. Batches are marked recoverable using RecoverableBatch.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val RELAX_SUBQUERY_REWRITE_CONDITION_AND_MOVE_RULE_UP = perfPackFlag(
      key = "spark.databricks.optimizer.relaxSubqueryRewriteConditionAndMoveRuleUp",
      doc = "When true, early subquery unnesting happens even earlier, and stats and inner join " +
        "conditions are no longer required for early unnesting.",
      owner = "eng-qo-team")

    val EXECUTE_EXTRA_OPTIMIZATION_BATCH_BEFORE_JOIN_REORDER = perfPackFlag(
      key = "spark.databricks.optimizer.executeExtraOptimizationBatchBeforeJoinReorder",
      doc = "When true, extraOptimizationBatch is executed prior to Join Reordering.",
      owner = "eng-qo-team")

    val DEDUP_ONE_ROW_RELATIONS_IN_REORDER_JOIN =
      buildConf("spark.databricks.optimizer.dedupOneRowRelationsInReorderJoin")
        .internal()
        .doc("When true, adds extra handling of OneRowRelations in ReorderJoins rule.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val HANDLE_PROJECT_UNDER_LIMIT_IN_SUBQUERIES =
      buildConf("spark.sql.optimizer.handleProjectUnderLimitInSubqueries.enabled")
        .internal()
        .doc("Handles project under Limit in correlated scalar subqueries.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val PREPARE_DELTA_SCAN_PRIOR_TO_JOIN_REORDER = perfPackFlag(
      key = "spark.databricks.optimizer.prepareDeltaScanPriorToJoinReorder",
      doc = "When true, execute Prepare Delta Scan rule prior to join reordering to make use of " +
        "delta stats throughout the optimizer later on. This flag, however, only controls the " +
        "location of the rule, and does not enable further stats propagation/usage.",
      owner = "eng-qo-team")

    val CAP_FILTERED_ROW_COUNT_BY_ROW_COUNT_AFTER_PRUNING = perfPackFlag(
      key = "spark.databricks.optimizer.capFilteredRowByRowCountAfterPruning",
      doc = "When on, caps the estimated number of rows after filter selectivities by rows" +
        "remaining after partition and file pruning.",
      owner = "eng-qo-team",
      fallback = ACCEPT_SOAKING_FEATURES)(f => f)

    val ESTIMATE_SIZE_IN_BYTES_FROM_DELTA_FOR_FIXED_WIDTH = perfPackFlag(
      key = "spark.databricks.optimizer.estimateSizeInBytesFromDeltaFixedWidth",
      doc = "When on, estimate stats for Projects with fixed-sized only outputs on top of " +
       "Filter->DeltaTable using remaining row counts after file and partition pruning, when no " +
       "optimizer stats is present.",
      owner = "eng-qo-team")

    val ESTIMATE_SIZE_IN_BYTES_FIXED_WIDTH_LOG_BHJ_IN_JOIN_TRACKER = perfPackFlag(
      key = "spark.databricks.optimizer.estimateSizeInBytesFixedWidthLogBhjInJoinTracker",
      doc = "When on and `spark.databricks.optimizer.estimateSizeInBytesFromDeltaFixedWidth` is " +
        "on, log join events during static planning if they are _only_ broadcastable via " +
        "uncompressed estimation (with fixed-sized types).",
      owner = "eng-qo-team",
      default = true)

    val PREPARE_DELTA_SCAN_DETECT_NEW_FILTERS =
      buildConf("spark.databricks.optimizer.prepareDeltaScanDetectNewFilters")
        .internal()
        .doc("When true, executes PrepareDeltaScanDetectNewFilters rule in the original location " +
          "of the PDS rule. Only effective when PREPARE_DELTA_SCAN_PRIOR_TO_JOIN_REORDER is ON. " +
          "For more details, see docstring for the PrepareDeltaScanDetectNewFilters rule.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(false)

    val ATTACH_DELTA_STATS_TO_LOGICAL_RELATION = edgeFlag(
      key = "spark.databricks.optimizer.attachDeltaStatsToLogicalPlan",
      doc = "When true, DeltaStatistics objects will be created and attached to LogicalRelation " +
        "nodes after PrepareDeltaScan.",
      owner = "eng-qo-team",
      default = true)

    val PROJECT_METADATA_OUTPUT_SHORT_CIRCUIT_ENABLED =
      buildConf("spark.databricks.optimizer.project.metadataOutput.shortCircuit.enabled")
        .internal()
        .doc("When enabled, Project.metadataOutput returns Nil unless hidden metadata is set, " +
          "to avoid deep recursive scans on large nested projects.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val FILTER_ESTIMATION_TRACING = perfPackFlag(
      key = "spark.databricks.optimizer.filterEstimationTracing",
      doc = "When ON, enables printing detailed logs during filter estimation.",
      owner = "eng-qo-team",
      default = false)

    val DYNAMIC_FILE_PRUNING = edgeFlag(
      key = "spark.databricks.optimizer.dynamicFilePruning",
      doc = "When true, the optimizer will insert custom min-max predicates for data skipping. " +
        "Dynamic file pruning is only triggered by join operations on Delta tables.")

    val ENABLE_ALLOWLIST_FOR_VALIDATE_AGGREGATE_EXPRESSIONS =
      buildConf("spark.databricks.optimizer.EnableAllowListForValidateAggregateExpressions")
        .internal()
        .doc("Whether to skip checking for attributes in allowlist" +
          "(eg. generated join predicate for EXISTS join) in validateAggregateExpressions.")
        .owner("eng-qo-team")
        .fallbackConf(ACCEPT_SOAKING_FEATURES)

    val HANDLE_INSUBQUERIES_WITH_AGGREGATE_EXPRESSIONS_IN_VALUES =
      buildConf("spark.databricks.optimizer.handleInSubqueriesWithAggregateExpressionsInValues")
        .internal()
        .doc("When true, the optimizer will handle in-subqueries with aggregate expressions " +
          "in values clause.")
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val REMOVE_DYNAMIC_PRUNING_IN_FINISH_ANALYSIS = edgeFlag(
      key = "spark.databricks.optimizer.removeDynamicPruningInFinishAnalysis",
      doc = "When true, removes dynamic prunings in FinishAnalysis")

    val REMOVE_DYNAMIC_PRUNING_FOR_STATIC_FILE_PRUNING =
      buildConf(key = "spark.databricks.optimizer.removeDynamicPruningForStaticFilePruning")
        .internal()
        .owner("eng-qo-team")
        .doc("When true, removes dynamic pruning markers during static file pruning while " +
          "de-duping relations")
        .booleanConf
        .createWithDefault(true)

    val FORCE_DYNAMIC_PRUNING_DIMENSION_TABLE_THRESHOLD =
      buildConf("spark.databricks.optimizer.forceDynamicPruningDimensionTableThreshold")
      .internal()
      .doc("A join input is considered as a dimension table if its size is no larger than this " +
        "threshold.")
      .bytesConf(ByteUnit.BYTE)
      .createWithDefaultString("1MB")

    val FORCE_DYNAMIC_PRUNING_WITH_DIMENSION_TABLES = perfPackFlag(
      key = "spark.databricks.optimizer.forceDynamicPruningWithDimensionTables",
      doc = "When true, force to introduce dynamic pruning filters from dimension tables, " +
        s"whose size is less smaller than ${FORCE_DYNAMIC_PRUNING_DIMENSION_TABLE_THRESHOLD.key}, "
