    val ENSURE_REQUIREMENTS_DP_DO_NOT_OPTIMIZE_WHEN_NO_STATS = perfPackFlag(
      key = "spark.databricks.sql.optimizer.ensureRequirementsDPDoNotOptimizeWhenNoStats.enable",
      doc = "If true, when the plan's leaves have no stats," +
        " return earlier from EnsureRequirementsDP",
      owner = "eng-qo-team",
      fallback = ACCEPT_SOAKING_FEATURES)(f => f)

    val ENSURE_REQUIREMENTS_DP_DO_NOT_RUN_WITH_AUTO_STATS =
      buildConf("spark.databricks.sql.optimizer.ensureRequirementsDPDoNotRunWithAutoStats.enable")
