    val ENSURE_REQUIREMENTS_DP_DO_NOT_PUSHDOWN_SINGLE_PARTITION_SHUFFLE_GENERATED_BY_UNARY_NODE =
      perfPackFlag(
        key = "spark.databricks.sql.optimizer.ensureRequirementsDP." +
          "doNotPushDownSinglePartitionShuffleGeneratedByUnaryNode",
        doc = "If true, do not push down shuffles from unary nodes which create single partition",
