        fallback = ACCEPT_SOAKING_FEATURES)(f => f)

    val ENSURE_REQUIREMENTS_DP_DO_NOT_PUSHDOWN_SINGLE_PARTITION_SHUFFLE_GENERATED_BY_JOIN =
      perfPackFlag(
        key = "spark.databricks.sql.optimizer.ensureRequirementsDP." +
          "doNotPushDownSinglePartitionShuffleGeneratedByJoin",
        doc = "If true, do not push down shuffles from joins which create single partition",
