        fallback = ACCEPT_SOAKING_FEATURES)(f => f)

    val ENSURE_REQUIREMENTS_DP_NO_LOW_PARALLELISM_SHUFFLE =
      buildConf("spark.databricks.sql.optimizer.ensureRequirementsDP.noLowParallelismShuffle")
        .internal()
        .doc("If true, do not push down low parallelism shuffles and " +
