        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val ENSURE_REQUIREMENTS_DP_LOW_PARALLELISM_THRESHOLD =
      buildConf("spark.databricks.sql.optimizer.ensureRequirementsDP.lowParallelismThreshold")
      .internal()
      .doc("Threshold for generating request distribution combinations in ensureRequirementsDP. " +
        "EnsureRequirementsDP doesn't generate shuffles partitioned on columns " +
