        .booleanConf
        .createWithDefault(true)

    val ENSURE_REQUIREMENTS_DP_SIZE_THRESHOLD_WITHOUT_SUBQUERIES =
      buildConf("spark.databricks.sql.optimizer.ensureRequirementsDP.nodeSizeWithoutSubqueries")
