    val ENSURE_REQUIREMENTS_DP_SCAN_SIZE_THRESHOLD =
      buildConf("spark.databricks.sql.optimizer.ensureRequirementsDP.scanSizeThresholdInBytes")
        .internal()
        .doc("Minimum total scan size in bytes for a single query to use EnsureRequirementsDP")
