    val MAX_ALIAS_REPLACEMENT_PROJECT_LIST_SIZE =
      buildConf("spark.databricks.sql.optimizer.maxAliasReplacementProjectListSize")
        .doc("Alias replacement will be skipped if the number of aliased expressions in a " +
