        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(false)

    val ANALYZE_TABLE_INCREMENTALLY =
      buildConf("spark.databricks.sql.optimizer.analyzeTableIncrementally.enabled")
        .internal()
        .doc("Incrementally collect table stats when running the ANALYZE command.")
        .booleanConf
        .createWithDefault(false)

    val ANALYZE_TABLE_STALENESS_THRESHOLD =
      buildConf("spark.databricks.sql.optimizer.AnalyzeTableStalenessThreshold")
        .internal()
        .doc("Skip collecting stats in ANALYZE if the stats staleness is below the threshold. " +
          "A negative value disables the staleness check and a positive value sets a threshold.")
        .intConf
        .checkValue(threshold => threshold >= -1 && threshold <= 100,
                    "The threshold must be in this range [-1, 100].")
        .createWithDefault(0) // Enabled with 0 threshold

