      buildConf("spark.databricks.sql.optimizer.statisticsAsyncUpdate.mergePendingStats")
        .internal()
        .doc("Whether to merge pending statistics updates before updating the table's " +
          "statistics.")
        .booleanConf
        .createWithDefault(true)

    val STATISTICS_ASYNC_DELTA_UPDATE =
      buildConf("spark.databricks.sql.optimizer.statisticsAsyncUpdate.enabled")
        .internal()
        .doc("Whether Delta-based statistics are updated asynchronously. The " +
          "spark.databricks.sql.optimizer.storeNdvSketchesOnDataLoad.enabled flag must also be " +
          "set to true for this flag to take effect.")
        .booleanConf
        .createWithDefault(true)

    val STATISTICS_ASYNC_NQL_LOGGING =
      buildConf("spark.databricks.sql.optimizer.statisticsAsyncUpdate.nqlLogging.enabled")
        .internal()
        .doc("When spark.databricks.sql.optimizer.statisticsAsyncUpdate.enabled is true, " +
          "Optimizer statistics collected on ingestion will be incorporated asynchronously. " +
          "As statistics is best effort, if any exception raised in background, the foreground " +
