    object DynamicPruningConfiguration extends Enumeration {
      // We can represent the below as tuple[soaking, current], where each tuple represents
      // the datastructure that is enabled in either soaking or not soaking. (SC-191545)
      // We only instantiate the configs that are useful for rollout. See go/dfp-dpp-rollout
      val DISABLED = Value("DISABLED")                                 // (None, None)
      val INSUBQUERY = Value("INSUBQUERY")                             // (InSubquery, InSubquery)
      val RANGE_FILTER = Value("RANGE_FILTER")                         // (RangeFilter, RangeFilter)
      val UNRESTRICTED = Value("UNRESTRICTED")                         // (Both, Both)
      val INSUBQUERY_SOAKING = Value("INSUBQUERY_SOAKING")             // (InSubquery, None)
      val UNRESTRICTED_SOAKING = Value("UNRESTRICTED_SOAKING")         // (Both, None)
      val UNRESTRICTED_IF_SOAKING_ELSE_INSUBQUERY =                    // (Both, InSubquery)
        Value("UNRESTRICTED_IF_SOAKING_ELSE_INSUBQUERY")

      val valueStrings = values.map(_.toString)
      val insubqueryEnabledStrings: Seq[String] = Seq(UNRESTRICTED, UNRESTRICTED_SOAKING,
        UNRESTRICTED_IF_SOAKING_ELSE_INSUBQUERY, INSUBQUERY, INSUBQUERY_SOAKING).map(_.toString)
      val rbfEnabledStrings: Seq[String] = Seq(UNRESTRICTED, UNRESTRICTED_SOAKING,
        UNRESTRICTED_IF_SOAKING_ELSE_INSUBQUERY, RANGE_FILTER).map(_.toString)
    }

