    val ADAPTIVE_JOIN_FALLBACK =
      buildConf("spark.databricks.adaptive.joinFallback")
        .doc("When true and if EBJ is enabled, convert a broadcast hash join to a shuffle " +
          "join at runtime if runtime statistics show that the build side is above a threshold")
        .internal()
        .booleanConf
        .createWithDefault(true)

    val ADAPTIVE_JOIN_FALLBACK_THRESHOLD =
      buildConf("spark.databricks.adaptive.joinFallback.threshold")
        .doc("The size threshold of the build side over which a broadcast join will try to fall" +
          " back to either a shuffle join or a broadcast join with a flipped build side.")
        .internal()
        .bytesConf(ByteUnit.BYTE)
        .createWithDefaultString("300MB")

    val ADAPTIVE_OUT_OF_MEMORY_JOIN_FALLBACK =
      buildConf("spark.databricks.adaptive.outOfMemory.joinFallback")
        .doc("When true and if EBJ is enabled, convert a broadcast hash join to a shuffle " +
          "join at runtime if the broadcast has caused OutOfMemory error")
        .internal()
        .booleanConf
        .createWithDefault(true)

    val ADAPTIVE_JOIN_FALLBACK_CANCEL_BUILD_SIDE =
      buildConf("spark.databricks.adaptive.joinFallback.cancelBuildSide")
        .doc("When true, cancel a fallbacked broadcast hash join build side to improve " +
          "re-shuffle parallelism.")
        .internal()
        .booleanConf
        .createWithDefault(true)

    val ADAPTIVE_RUNTIME_BLOOM_FILTER_MIN_NUM_BITS =
      buildConf("spark.databricks.adaptive.bloomFilter.minNumBits")
        .doc("The min number of bits to use for the runtime bloom filter injected during AQE")
        .internal()
        .longConf
        .createWithDefault(1L)

    private def maxNumBitsForExplicitScheduling(): Long =
      if (SQLConf.get.getConf(ACCEPT_SOAKING_FEATURES)) {
        128 * 1024 * 1024 * 8L
      } else {
        64 * 1024 * 1024 * 8L
      }

    val ADAPTIVE_RUNTIME_BLOOM_FILTER_MAX_NUM_BITS =
      buildConf("spark.databricks.adaptive.bloomFilter.maxNumBits")
        .doc("The max number of bits to use for the runtime bloom filter injected during AQE")
        .internal()
        .longConf
        .createWithDefaultFunction(maxNumBitsForExplicitScheduling)

    val ADAPTIVE_RUNTIME_BLOOM_FILTER_MAX_NUM_BITS_COST_MODEL_FALLBACK =
      buildConf("spark.databricks.adaptive.bloomFilter.maxNumBitsCostModelFallback")
        .doc("The max number of bits to use for the runtime bloom filter injected during AQE " +
          "with the cost-model based injection criteria as a fallback when photon is not " +
          "enabled or the stage could not be photonized.")
        .internal()
        .owner("eng-qo-team")
        .longConf
        .createWithDefault(32 * 1024 * 1024 * 8L)

    val ADAPTIVE_RUNTIME_BLOOM_FILTER_MAX_NUM_BITS_CANCELLATION =
      buildConf("spark.databricks.adaptive.bloomFilter.maxNumBitsCancellation")
        .doc("The max number of bits to use for the runtime bloom filter injected during AQE" +
          "using the old cancellation-based criteria. This configuration is kept separate from" +
          "the cost-based criteria maxNumBits configs.")
        .internal()
        .owner("eng-qo-team")
        .longConf
        .createWithDefault(32 * 1024 * 1024 * 8L)

    val ADAPTIVE_BYPASS_DYNAMIC_PRUNING_THRESHOLD =
      buildConf("spark.databricks.adaptive.bypassDynamicPruning.threshold")
        .doc("The maximum number of distinct values for applying dynamic pruning in " +
          "executor-side broadcast hash joins or shuffled joins, above which we will bypass " +
          "dynamic pruning if this is not a broadcast join introduced by hints.")
        .internal()
        .intConf
        .checkValue(_ > 0, "Bypass dynamic pruning threshold must be a positive integer.")
        .createWithDefault(3000000)

    val ADAPTIVE_BYPASS_DYNAMIC_PRUNING_IGNORE_BROADCAST_HINT =
      buildConf("spark.databricks.adaptive.bypassDynamicPruning.ignoreBroadcastHint")
        .doc(s"When true, still bypass dynamic pruning according to " +
          s"${ADAPTIVE_BYPASS_DYNAMIC_PRUNING_THRESHOLD} even if the join has a broadcast hint.")
        .internal()
        .owner("eng-qo-team")
        .booleanConf
        .createWithDefault(true)

    val EXPLICIT_SCHEDULING_WITH_INSUBQUERY_NDV_LIMIT = buildConf(
      "spark.databricks.adaptive.dfpExplicitSchedulingWithInSubquery.ndvLimit")
      .doc("The maximum NDV count for the build side of the inList for DFP/DPP by explicit " +
        "scheduling. If the NDV count for the build side is higher than this, don't inject.")
      .internal()
      .owner("eng-qo-team")
      .fallbackConf(ADAPTIVE_BYPASS_DYNAMIC_PRUNING_THRESHOLD)

    val ADAPTIVE_DYNAMIC_PRUNING_EXPLICIT_STAGE_REUSE =
      buildConf("spark.databricks.adaptive.dynamicPruningExplicitStageReuse.enabled")
        .doc("When true, allows explicit stage reuse for dynamic pruning during AQE.")
        .internal()
        .owner("eng-photon-team")
        .booleanConf
        .createWithDefault(true)

    val ADAPTIVE_SUBQUERY_STAGE_REUSE =
      buildConf("spark.databricks.adaptive.subqueryStageReuse.enabled")
