        .internal()
        .owner("eng-qo-team")
        .fallbackConf(ADAPTIVE_RUNTIME_FILTERS_TRACING)

    val ADAPTIVE_DFP_TRACING =
      buildConf("spark.databricks.adaptive.dfp.trace")
        .doc("When true, generates extensive debugging logs for InjectRuntimeFilter and " +
          "AQEOptimizeRuntimeFilters for DFPs.")
        .internal()
        .owner("eng-qo-team")
        .fallbackConf(ADAPTIVE_RUNTIME_FILTERS_TRACING)

    val ADAPTIVE_DPP_TRACING =
      buildConf("spark.databricks.adaptive.dpp.trace")
        .doc("When true, generates extensive debugging logs for InjectRuntimeFilter and " +
