        .internal()
        .owner("eng-qo-team")
        .fallbackConf(ADAPTIVE_RUNTIME_FILTERS_TRACING)

    val ADAPTIVE_MULTI_COLUMN_BLOOMS_FILTERS_ENABLED = perfPackFlag(
      key = "spark.databricks.adaptive.bloomFilter.multicolumn.enabled",
      doc = "When true, multi-column Bloom filters are injected during AQE for shuffle joins " +
        "when applicable. Enabled only when dynamic bloom filters with explicit build followed" +
        s"by probe scheduling is enabled by config " +
        s"${ADAPTIVE_BLOOM_FILTERS_EXPLICIT_BUILD_PROBE_SCHEDULING.key}",
      fallback = ADAPTIVE_BLOOM_FILTERS_EXPLICIT_BUILD_PROBE_SCHEDULING)(f => f)

    val ADAPTIVE_BHJ_CHAIN = perfPackFlag(
      key = "spark.databricks.adaptive.BHJChain.enabled",
      doc = "When true, checks the total memory consumption of a chain of BHJ",
      owner = "eng-qo-team",
      default = true)

    val TOTAL_BHJ_MAXIMUM_MEMORY_USAGE_PERCENTAGE =
      buildConf("spark.databricks.adaptive.BHJChainMaxMemoryPercentage.default")
        .internal()
        .doc("A configuration parameter specifying the default memory usage percentage for the" +
          " chain of BHJ, beyond this threshold we will convert some of the joins into" +
          " Shuffle joins.")
        .owner("eng-qo-team")
        .doubleConf
        .checkValue(threshold => threshold >= 0.05 && threshold <= 5,
          "The threshold must be in this range [0.05, 5.0].")
        .createWithDefault(0.8)

    val ADAPTIVE_BHJ_CHAIN_MEMORY_COMPUTATION_FACTOR =
      buildConf("spark.databricks.adaptive.BHJChain.factor")
        .doc("The parameter specifying how much more memory a hash table takes compared " +
          "to the input size: the total hash table size is assumed to be " +
          "ADAPTIVE_BHJ_CHAIN_MEMORY_COMPUTATION_FACTOR * input_size")
        .owner("eng-qo-team")
        .internal()
        .doubleConf
        .createWithDefault(3.0)

    val ADAPTIVE_BHJ_CHAIN_IGNORE_HINTS =
      buildConf("spark.databricks.adaptive.BHJChain.ignoreHints")
        .doc("If true, ignores broadcast hints when converting broadcast-to-shuffle joins as" +
          " part of AdaptiveBHJChainSplitter rule. Internal usage.")
        .owner("eng-qo-team")
        .internal()
        .booleanConf
        .createWithDefault(false)


    val BLOOM_FILTERS_ON_ANTI_JOINS_ENABLED = perfPackFlag(
      key = "spark.databricks.adaptive.bloomFilter.antiJoin.enabled",
      doc = "If true, bloom filters are injected on the right side of anti join when applicable " +
        "and beneficial.")

    val BLOOM_FILTERS_CASCADED_ENABLED = perfPackFlag(
      key = "spark.databricks.adaptive.bloomFilter.cascaded.enabled",
      doc = "If true, bloom filters are considered to be injected in a cascaded fashion " +
        "to optimize snowflake type schemas")

    val TRANSITIVITY_BLOOM_FILTERS = perfPackFlag(
      key = "spark.databricks.adaptive.bloomFilter.transitiveBloomFilter.enabled",
      doc = "When true, includes transitively derived predicates for bloom filter placement")

    val BLOOM_FILTERS_FOR_BROADCAST_JOINS_PROBE_SIDE_MIN_ROWS =
      buildConf("spark.databricks.adaptive.bloomFilter.broadcastJoinProbeMinRows")
        .doc("The threshold minimum number of rows for the probe side to consider " +
        "injecting a Bloom filter for a broadcast hash join without a shuffle on the probe side.")
        .internal()
        .longConf
        .createWithDefault(1e9.toLong)

    val BLOOM_FILTERS_FOR_BROADCAST_JOINS_MAX_BLOOM_SIZE =
      buildConf("spark.databricks.adaptive.bloomFilter.broadcastJoinMaxBloomFilterSize")
        .doc("The threshold maximum Bloom filter size, in bytes, to consider injecting a " +
          "Bloom filter for a broadcast hash join without a shuffle on the probe side.")
        .internal()
        .longConf
        .createWithDefault(1024)

    val MAX_BLOOM_FILTER_SELECTIVITY_FOR_BROADCAST_JOINS =
      buildConf("spark.databricks.adaptive.bloomFilter.broadcastJoinMaxBloomFilterSelectivity")
        .doc("The threshold maximum Bloom filter selectivity to consider injecting a Bloom " +
          "filter for a broadcast hash join without a shuffle on the probe side.")
        .internal()
        .doubleConf
        .createWithDefault(0.5)

    val BLOOM_FILTERS_FOR_BROADCAST_JOINS_MIN_HASH_TABLE_SIZE =
      buildConf("spark.databricks.adaptive.bloomFilter.broadcastJoinMinHashTableSize")
        .doc("The threshold minimum hash table size, in bytes, for the broadcast hash join " +
          "to consider injecting a Bloom filter for a broadcast hash join without a shuffle on " +
          "the probe side.")
        .internal()
        .doubleConf
        .createWithDefault(5 * 1024 * 1024)

    val BLOOM_FILTERS_PROPAGATE_STATS_THROUGH_EXPRESSION = perfPackFlag(
          key = "spark.databricks.adaptive.bloomFilter.propagateStatsThroughExpression",
          doc = "When enabled, use stats through expressions for Bloom filters. Requires " +
            "spark.databricks.optimizer.propagateStatsJoinedExpressions.enabled to be enabled.",
          owner = "eng-qo-team",
          default = true)

    val BLOOM_FILTERS_EXTRACT_ELEMENT_MERGE_SCALAR_SUBQUERY_ENABLED =
      buildConf("spark.databricks.adaptive.bloomFilter.extractElementMergeScalarSubquery.enabled")
        .doc("When enabled, ExtractBloomFilterElements can extract bloom filter elements from " +
          "a merged scalar subquery.")
        .internal()
        .booleanConf
        .createWithDefault(true)

    val BLOOM_FILTERS_NUM_SHUFFLES_TO_CONSIDER_ON_BUILD_SIDE =
      buildConf("spark.databricks.adaptive.bloomFilter.numShufflesToConsiderOnBuildSide")
        .doc("Determines the number of shuffles from lowest to the highest to consider as the " +
          "build side for bloom creation.")
        .internal()
        .intConf
        .checkValue(_ > 0, "Number of shuffles to consider on build side must be positive.")
        .createWithDefault(2)

    val BLOOM_FILTERS_CONSIDER_MULTIPLE_SHUFFLES_ON_BUILD_SIDE =
      buildConf("spark.databricks.adaptive.bloomFilter.considerMultipleShufflesOnBuildSide")
        .doc("Determines whether to consider bloom potential heuristically based on the higher" +
          "shuffles (including the lowest shuffle) to delay the placeholder clean up even when " +
          "the cost-model does not qualify the bloom filters. Note, when enabled, the clean up " +
          "logic delays the placeholder clean up even when the stage is considered materialized " +
          "in the ShuffleExecutionState check but is not a materialized LogicalQueryStage.")
        .internal()
        .booleanConf
        .createWithDefault(true)

    val COMPARE_BOTH_PROBE_AND_BUILD_KEY_FOR_BLOOM_FILTER_PLACEHOLDERS =
      buildConf("spark.databricks.adaptive.bloomFilter." +
        "compareProbeAndBuildKeyForBloomFilterPlaceholders")
        .doc("When true, compare both the probe key and the build key for the hasRuntimeFilter " +
          "check thereby allowing multiple runtime filters on the probe side with different " +
          "build keys.")
        .owner("eng-qo-team")
        .internal()
        .booleanConf
        .createWithDefault(true)

    val ADAPTIVE_SCHEDULER_USE_CUSTOM_PRIORITY =
      perfPackFlag(
        key = "spark.databricks.adaptive.scheduler.useSchedulerPriority",
        doc = "When enabled, we submit a user defined priority when submitting stages during" +
            " AQE. Currently, this priority is directly proportional to task number in a stage," +
            " which means that small stages are prioritized by the DAGScheduler over larger" +
            " stages. This heuristics will make AQE decision more deterministic and is" +
            " beneficial for increasing the chance of Bloom filter injection," +
            " DPP and cancelling shuffle stages when converting to broadcast join" +
            " opportunities during AQE.")

    val ADAPTIVE_BLOOM_FILTER_FALLBACK_NON_PHOTONIZED_STAGE_ENABLED =
      perfPackFlag(
        key = "spark.databricks.adaptive.bloomFilter.fallbackNonPhotonizedStage.enabled",
        doc = "When true, bloom filters in stages that could not be photonized are removed if" +
          "they are larger than ADAPTIVE_BLOOM_FILTER_FALLBACK_NON_PHOTONIZED_STAGE_THRESHOLD." +
          "This is to avoid potential executor OOM(s) due to memory overhead of bloom filter " +
          "evaluation in Spark.",
        owner = "eng-qo-team",
        default = true
      )

    val ADAPTIVE_BLOOM_FILTER_FALLBACK_NON_PHOTONIZED_STAGE_THRESHOLD =
      buildConf("spark.databricks.adaptive.bloomFilter.fallbackNonPhotonizedStage.threshold")
        .doc("The max number of bits allowed for a bloom filter in a non-photonized stage when" +
          "perfpack is enabled. Bloom filters larger than this threshold are removed to prevent" +
          "potential executor OOM(s).")
        .owner("eng-qo-team")
        .internal()
        .fallbackConf(ADAPTIVE_RUNTIME_BLOOM_FILTER_MAX_NUM_BITS_COST_MODEL_FALLBACK)

    /**
     * This config is for testing purpose only. AOS 2.0 will automatically use uncompressed stats.
     */
    val TEST_USE_UNCOMPRESSED_SHUFFLE_SIZE =
      buildConf("spark.databricks.adaptive.test.useUncompressedShuffleSize")
        .doc(s"Test only: when true, AQE feature including coalescing and skew handling will use " +
          s"uncompressed shuffle size.")
        .version("4.0.0")
        .owner("eng-photon-team")
        .booleanConf
        .createWithDefault(false)

    val UNCOMPRESSED_ADVISORY_PARTITION_SIZE_IN_BYTES =
      buildConf("spark.sql.adaptive.uncompressedAdvisoryPartitionSizeInBytes")
        .doc("The uncompressed advisory size in bytes of the shuffle partition during adaptive " +
          "optimization(when AQE is enabled). It takes effect when Spark coalesces small shuffle " +
          "partitions or splits skewed shuffle partition.")
        .version("4.0.0")
        .owner("eng-photon-team")
        .bytesConf(ByteUnit.BYTE)
        .createWithDefaultString("192MB")

    val ADAPTIVE_WRAP_DATASET_CHECKPOINT =
      buildConf("spark.sql.adaptive.wrapDatasetCheckpoint")
        .doc("When true, AQE will wrap Dataset.checkpoint() execution with" +
          "aqe.withFinalPlanUpdate in order to properly use AQE in the result stage")
        .internal()
        .owner("eng-photon-team")
        .booleanConf
        .createWithDefault(true)
  } // End of AdaptiveExecution

  object DatabricksJdbc {
    val USE_DATABRICKS_JDBC_OSS_DRIVER =
      buildConf("spark.databricks.jdbc.ossDriverEnabled")
        .internal()
        .doc("If true, JDBC OSS driver is used for Databricks JDBC connections in Spark SQL.")
        .booleanConf
        .createWithDefault(false)
  } // End of DatabricksJdbc

  def explicitSchedulingForDynamicBloomFiltersEnabled: Boolean =
    SQLConf.get.getConf(AdaptiveExecution.ADAPTIVE_BLOOM_FILTERS_EXPLICIT_BUILD_PROBE_SCHEDULING) &&
      SQLConf.get.getConf(AdaptiveExecution.ADAPTIVE_RUNTIME_FILTER_INJECTION) &&
      SQLConf.get.getConf(SQLConf.ADAPTIVE_EXECUTION_ENABLED)

  def explicitSchedulingForDynamicFilePruningEnabled: Boolean =
    SQLConf.get.getConf(AdaptiveExecution.ADAPTIVE_RUNTIME_FILTER_INJECTION) &&
      SQLConf.get.getConf(SQLConf.ADAPTIVE_EXECUTION_ENABLED) &&
      SQLConf.get.getConf(
        AdaptiveExecution.ADAPTIVE_DFP_EXPLICIT_BUILD_PROBE_SCHEDULING)

  def explicitSchedulingForDFPForBroadcastJoinsEnabled: Boolean =
    explicitSchedulingForDynamicFilePruningEnabled &&
      SQLConf.get.getConf(AdaptiveExecution.DFP_EXPLICIT_SCHEDULING_FOR_BROADCAST_JOINS) && (
      (SQLConf.get.getConf(AdaptiveExecution.DFP_EXPLICIT_SCHEDULING_WITH_INSUBQUERY) &&
        AdaptiveExecution.DynamicPruningConfiguration.insubqueryEnabledStrings.contains(
          SQLConf.get.getConf(AdaptiveExecution.DFP_EXPLICIT_SCHEDULING_FOR_BROADCAST_DS))) ||
        (SQLConf.get.getConf(AdaptiveExecution.DFP_EXPLICIT_SCHEDULING_WITH_RBF) &&
          AdaptiveExecution.DynamicPruningConfiguration.rbfEnabledStrings.contains(
            SQLConf.get.getConf(AdaptiveExecution.DFP_EXPLICIT_SCHEDULING_FOR_BROADCAST_DS))))

  def explicitSchedulingForDPPForBroadcastJoinsEnabled: Boolean =
    explicitSchedulingForDynamicPartitionPruningEnabled &&
      SQLConf.get.getConf(AdaptiveExecution.DPP_EXPLICIT_SCHEDULING_FOR_BROADCAST_JOINS) && (
      (SQLConf.get.getConf(AdaptiveExecution.DPP_EXPLICIT_SCHEDULING_WITH_INSUBQUERY) &&
        AdaptiveExecution.DynamicPruningConfiguration.insubqueryEnabledStrings.contains(
          SQLConf.get.getConf(AdaptiveExecution.DPP_EXPLICIT_SCHEDULING_FOR_BROADCAST_DS))) ||
        (SQLConf.get.getConf(AdaptiveExecution.DPP_EXPLICIT_SCHEDULING_WITH_RBF) &&
          AdaptiveExecution.DynamicPruningConfiguration.rbfEnabledStrings.contains(
            SQLConf.get.getConf(AdaptiveExecution.DPP_EXPLICIT_SCHEDULING_FOR_BROADCAST_DS))))

  def explicitSchedulingForDynamicPartitionPruningEnabled: Boolean =
    SQLConf.get.getConf(AdaptiveExecution.ADAPTIVE_RUNTIME_FILTER_INJECTION) &&
      SQLConf.get.getConf(SQLConf.ADAPTIVE_EXECUTION_ENABLED) &&
      SQLConf.get.getConf(
        AdaptiveExecution.ADAPTIVE_DPP_EXPLICIT_BUILD_PROBE_SCHEDULING)

  def maxNumBitsForExplicitSchedulingBasedBloomFilter: Long = {
    if (SQLConf.get.getConf(PHOTON_ENABLED)) {
      SQLConf.get.getConf(AdaptiveExecution.ADAPTIVE_RUNTIME_BLOOM_FILTER_MAX_NUM_BITS)
    } else {
      SQLConf.get.getConf(AdaptiveExecution.
        ADAPTIVE_RUNTIME_BLOOM_FILTER_MAX_NUM_BITS_COST_MODEL_FALLBACK)
    }
  }

  /**
   * @return true if explicit scheduling framework applies for this query. This is true when all of
   *         the below is true:
   *         1. Explicit scheduling config is enabled.
   *         2. Query is either not a command OR config for command is enabled.
   */
  def explicitSchedulingAppliesForThisQuery: Boolean =
    explicitSchedulingForDynamicBloomFiltersEnabled &&
      (SQLConf.get.getConf(AdaptiveExecution.ENABLE_EXPLICIT_SCHEDULING_FOR_COMMANDS) ||
        !CurrentQueryContext.currentIsExecutableCommand)

  def canUsePruningResultsForFilterEstimation: Boolean =
    SQLConf.get.getConf(Optimizer.MITIGATE_CORRELATED_PREDICATES) &&
      SQLConf.get.getConf(AdaptiveExecution.ADAPTIVE_JOIN_FALLBACK)

  def enableMySqlDriverBitMapping: Boolean =
    SQLConf.get.getConf(ENABLE_MYSQL_DRIVER_BIT_MAPPING)

  def legacyTimestampMapping: Boolean =
    SQLConf.get.getConf(LEGACY_TIMESTAMP_MAPPING)

  def postgresBitArrayMapping: Boolean =
    SQLConf.get.getConf(ENABLE_POSTGRES_BIT_ARRAY_MAPPING)

