    .internal()
    .owner("eng-osp")
    .doc("Sampling rate for logging a failing RPC request sent from DbfsClient")
    .doubleConf
    .checkValue(
      v => v >= 0.0 && v <= 1.0, "Sampling rate must be in the range [0, 1].")
    .createWithDefault(1) // 100%

