  val PREFER_SHUFFLED_HASH_JOIN_ON_SMALL_TABLES = perfPackFlag(
    key = "spark.databricks.join.preferShuffledHashJoin.enabled",
    doc = "If true, try to build a ShuffledHashJoin instead of a BroadcastHashJoin for " +
      "LeftOuter/LeftAnti/RightOuter/FullOuter joins, when the probe side is smaller " +
      "than the build side.")

