  val SQL_IGNORE_REDACT_NON_UTF8_BINARY =
    buildConf("spark.databricks.sql.ignoreRedactNonUTF8Binary")
      .internal()
      .doc("If disabled, redact binary values even if they represent invalid UTF8 characters. " +
        "This redaction takes place if the query contains one or more calls to the SECRET " +
        "SQL function, and the SQL compiler adds Redact expressions to a final projection " +
        "at the end of the query plan.")
      .owner("spark-platform")
      .booleanConf
