  val SQL_SUPPORT_UNWRAP_UNKNOWN_FIELD_EXCEPTION =
    buildConf("spark.databricks.sql.supportUnwrapUnknownFieldException")
      .internal()
      .doc("Kill switch to control whether UnknownFieldException" +
