  private val VALID_MDC_SPACE_FILLING_CURVES_NON_PERF_PACK = Set("zorder", "hilbert")
  val VALID_MDC_SPACE_FILLING_CURVES =
    if (DatabricksEdgeConfigs.perfPackEnabled) {
      VALID_MDC_SPACE_FILLING_CURVES_NON_PERF_PACK ++ Set("kdtree")
    } else {
      VALID_MDC_SPACE_FILLING_CURVES_NON_PERF_PACK
    }
  val DEFAULT_MDC_CURVE = if (DatabricksEdgeConfigs.perfPackEnabled) "kdtree" else "hilbert"
  val MDC_SPACE_FILLING_CURVE =
    buildConf("spark.databricks.io.skipping.mdc.curve")
      .internal()
      .doc("The space filling curve to use when performing multi dimensional clustering " +
        "(OPTIMIZE ZORDER BY).\n" +
        VALID_MDC_SPACE_FILLING_CURVES.map(c => s"""  "$c" - uses the $c space filling curve.""")
          .mkString("\n"))
      .stringConf
      .checkValues(VALID_MDC_SPACE_FILLING_CURVES)
      .createWithDefault(DEFAULT_MDC_CURVE)

  val MDC_RECORD_CURVE =
    buildConf("spark.databricks.io.skipping.mdc.record.curve")
      .internal()
      .doc("Boolean to enable recording of the space filling curve in the metadata for " +
        "files that are a part of a Z-ordered delta table.")
      .booleanConf
      .createWithDefault(true)

  val MDC_KDTREE_TARGET_SAMPLES_PER_PARTITION =
    buildConf("spark.databricks.io.skipping.mdc.kdtree.targetSamplesPerPartition")
      .internal()
      .doc("Number of samples to collect per partition for KdTree clustering.")
      .intConf
      .createWithDefault(100)

  val MDC_KDTREE_TARGET_SAMPLES_PER_PARTITION_SCALE_FACTOR =
    buildConf("spark.databricks.io.skipping.mdc.kdtree.targetSamplesPerPartitionScaleFactor")
      .internal()
      .doc("Controls the target samples per partition range while generating the KdTree." +
        " When set to 1.0, KdTree clustering will try to create leafs with samples in range" +
        " [targetSamplesPerPartition/2, targetSamplesPerPartition] which will correspond to file" +
        " sizes in range [targetFileSize/2, targetFileSize]. This is because we always split by a" +
        " factor of 2 until we are at or below targetSamplesPerPartition. When set to 1.2, KdTree" +
        " clustering will try to create leafs with samples in range" +
        " [targetSamplesPerPartition * 0.6, targetSamplesPerPartition * 1.2] which will" +
        " correspond to file sizes in range [targetFileSize * 0.6, targetFileSize * 1.2]. This is" +
        " to make sure that KdTree creates files around the targetFileSize.")
      .doubleConf
      .checkValue(p => p > 0, "Needs to be greater than 0.")
      .createWithDefault(1.2)

  // KdTree clustering performance degrades with WholeStageCodeGen enabled. The plan for KdTree has
  // nested case..when's. These nested case..when's gets WholeStageCodegened and the code size
  // reaches to around the 32KB limit but less than that. In this region, the performance degrades
  // drastically. Once the codegen crosses the 32KB limit (for large KdTrees), the performance
  // improves again as WSCG gets disabled automatically. This config makes sure that we don't use
  // WSCG with KdTree clustering.
  val MDC_KDTREE_DISABLE_WSCG =
    buildConf("spark.databricks.io.skipping.mdc.kdtree.disableWholeStageCodegen")
      .internal()
      .doc("When enabled, KdTree clustering is done with whole-stage codegen disabled.")
      .booleanConf
      .createWithDefault(true)

