  val STREAMING_REAL_TIME_MODE_MIN_BATCH_DURATION = buildConf(
    "spark.databricks.streaming.realTimeMode.minBatchDuration")
    .doc("The minimum long-running batch duration in milliseconds for real-time mode.")
    .owner("streaming-engine")
    .timeConf(TimeUnit.MILLISECONDS)
    .createWithDefault(5000)

  val STREAMING_REAL_TIME_MODE_ALLOWLIST_CHECK = buildConf(
    "spark.databricks.streaming.realTimeMode.allowlistCheck")
    .doc("Whether to check all operators, sinks used in real-time mode are in the allowlist.")
    .owner("streaming-engine")
    .booleanConf
    .createWithDefault(true)

  val STREAMING_REAL_TIME_WATERMARK_PROPAGATION_ENABLED =
    buildConf("spark.databricks.streaming.realTimeMode.realTimeWatermark.enabled")
    .internal()
    .doc("When enabled, if the query is in real-time mode and some operators can benefit from " +
      "watermark propagation in real-time, the query plan will be rewritten to support sending " +
      "watermark information within the stream of actual data messages. This can potentially " +
      "accelerate watermark advancement, and reduce the latency of some outputs. Note that " +
      "this feature is experimental, and it is not meant for production.")
    .owner("streaming-engine")
    .booleanConf
    .createWithDefault(false)

  val STREAMING_REAL_TIME_TRIGGER_OVERRIDE_SECONDS =
    buildConf("spark.databricks.streaming.realTimeTriggerOverrideSeconds")
      .doc("This is a temporary configuration that users can use to override their " +
        "streaming query's trigger to be the RealTimeTrigger with the specified checkpoint " +
        " interval. It is meant for Databricks customers who build JARs against OSS Spark and " +
        "cannot import the RealTimeTrigger object. It can be specified at the session level " +
        "or at the query level.")
      .owner("streaming-engine")
      .longConf
      .createWithDefault(0L)

  val STREAMING_REAL_TIME_MODE_SPARK_CONNECT_ENABLED =
    buildConf("spark.databricks.streaming.realTimeMode.sparkconnect.enabled")
