      .createWithDefault(true)

  val STREAMING_OPERATOR_PUSH_DOWN_ENABLED =
    buildConf("spark.sql.streaming.optimizer.operatorPushDown.enabled")
      .internal()
      .doc("Whether to push down operators to streaming sources. " +
        "Currently it only support V2 sources.")
      .booleanConf
      .createWithDefault(false)

  val STREAMING_VIEW_FILTER_PUSH_DOWN_ENABLED =
    buildConf("spark.sql.streaming.optimizer.viewFilterPushDown.enabled")
      .internal()
      .owner("streaming-engine")
      .doc("Whether to push down filter through views.")
      .booleanConf
      .createWithDefault(false)

  val STREAMING_ID_AWARE_LOGGING_ENABLED = buildConf(
