  val STATE_SCHEMA_CHECK_IGNORE_NULL_COMPATIBILITY =
    buildConf("spark.databricks.streaming.stateStore.stateSchemaCheck.ignoreNullCompatibility")
      .internal()
      .doc("When true, state schema checker will not check the nullability of columns " +
        "for compatibility validation of schema. Note that turning on this flag " +
        "could lead errors in runtime, e.g. when previous input schema has specific column as " +
        "nullable and it got changed to be non-nullable, stateful operator may read the old row " +
        "from state store (which may have the value of the column as `null`), and produce " +
        "output rows having value of the column as `null` which is not expected for downstream.")
      .booleanConf
      .createWithDefault(false)

  val STREAMING_DISABLE_INFINITE_TRIGGERS =
