  val ADAPTIVE_PHOTON_BLOOM_FILTER_RATE_MINIMUM_ROW_COUNT =
    buildConf("spark.databricks.photon.bloomFilterRateMinimumRowCount")
      .doc("Defines the minimum number of rows to check if bloom's filter rate is too low in " +
        "Photon. Setting this too small will cause bloom flipping between pass-through and " +
        "normal modes frequently based on small number of inputs, setting it too large will " +
        "cause it less useful. Defaults to 40960 rows which is 10 batches.")
      .version("3.3.0")
      .longConf
      .createWithDefault(4096 * 10)

  val ADAPTIVE_PHOTON_BLOOM_FILTER_RATE_THRESHOLD =
    buildConf("spark.databricks.photon.bloomFilterRateThreshold")
      .doc("Defines the filter rate threshold of a bloom to be effective. If a bloom's filter " +
        "rate is below this threshold, it will switch to pass-through mode. Defaults to filter " +
        "out at least 60% of input rows.")
      .version("3.3.0")
      .doubleConf
      .createWithDefault(0.6)

  val ADAPTIVE_PHOTON_BLOOM_FILTER_PASSTHROUGH_ROW_COUNT =
    buildConf("spark.databricks.photon.bloomFilterPassthroughRowCount")
      .doc("Number of rows to bypass Photon bloom filter when it's in pass-through mode. " +
        "Defaults to 409600 which is 10x of ADAPTIVE_PHOTON_BLOOM_FILTER_RATE_MINIMUM_ROW_COUNT " +
        "so that we can roughly bypass 90% of the input data when the filter is not selective.")
      .version("3.3.0")
      .longConf
      .createWithDefault(4096 * 100)

  val ADAPTIVE_PHOTON_BLOOM_FILTER_FIND_BRANCHING_REACTIVATE_ROW_COUNT =
