      .doc("Number of rows for Photon bloom filter to run in the branchless mode before " +
        "reactivating the branched probing")
      .longConf
      .checkValue(_ > 0, "value should be positive")
      .createWithDefault(4096 * 100)

  val ADAPTIVE_PHOTON_BLOOM_FILTER_FIND_BRANCHING_CHECK_MINIMUM_ROW_COUNT =
