  val CREDENTIALS_CLAUSE_FOR_SCALAR_PYTHON_UDFS_ENABLED =
    buildConf("spark.databricks.sql.python.credentialsClauseForScalarPythonUDFs.enabled")
      .internal()
      .publishConfigChangeEvents()
      .doc("Enable the use of the CREDENTIALS clause in the definition of scalar UC Python UDFs. " +
        "At the time of this flag's creation, this feature is enabled only for Batch Python UC " +
        "UDFs (also referred to as vectorized)")
      .owner("eng-lakestore-safe-spark")
      .booleanConf
      .createWithDefault(false)

  /**
   * The ENABLE_ENVIRONMENT_IN_EXTERNAL_UDF and UDF_ENVIRONMENT_SETTINGS_ENABLED are set as a
   * public preview flag.
   * Attention: We are using this public preview flag to also gate vectorized UDF.
   * The two environment confs should be i) merged into one and ii) renamed to reflect
   * that they control vectorized udfs, service creds, and environment support in UC Python UDFs.
   * @param conf - parameter to allow injecting conf
   * @return
   */
  def isPythonVectorizedUcUdfEnabled(conf: SQLConf): Boolean = {
    conf.getConf(PYTHON_VECTORIZED_UDF_SQL_ENABLED) &&
      conf.getConf(ENABLE_ENVIRONMENT_IN_EXTERNAL_UDF) &&
      conf.getConf(UDF_ENVIRONMENT_SETTINGS_ENABLED)
  }

