    .internal()
    .doc("If enabled, UC Python UDFs will be executed using the OSS PySpark codepath " +
      "(IsolatedPythonWorkerFactory, 'burrito', worker.py protocol)." +
      "If disabled, UC Python UDFs will be executed using the legacy ('taco') codepath " +
      "(EvalExternalUDFExec, Warmpool, udfserver.py protocol).")
    .owner("eng-lakestore-safe-spark")
    .booleanConf
    .createWithDefault(false)

  val MATERIALIZE_BETWEEN_UC_UDFS_ENABLED =
    buildConf("spark.databricks.sql.materializeBetweenUCUDFs.enabled")
      .internal()
      .publishConfigChangeEvents()
      .doc("If enabled, materialize intermediate results in-between UC UDFs" +
        "This can lead to increased memory/disk space usage, as all partitions are " +
        "materialized before calling the next UDF. This is only relevant for queries containing" +
        "more than one UDF call per stage.")
      .owner("eng-lakestore-safe-spark")
      .booleanConf
      .createWithDefault(true)

