        .longConf
        .createWithDefault(8L * 1024 * 1024)

    val OPTIMIZE_TABLE_ADVICE_NUMBER_SMALL_FILES_THRESHOLD =
      buildConf("spark.databricks.adviceGenerator.optimizeTableAdvice.numberSmallFilesThreshold")
