      .createWithDefault(false)

  val CLOUD_FILES_MISSING_FILES_LOGGING_ENABLED =
    buildConf("spark.databricks.cloudFiles.missingFilesLogging.enabled")
      .internal()
      .doc("ES-838426: enable logging to collect data for missing file events")
