  val NATIVE_IO_ENABLED = perfPackFlag(
    key = "spark.databricks.io.native.enabled",
    doc = "Use native I/O implementations when possible. This is the primary control for " +
      "enabling native I/O implementations. Use the specific flags below to control " +
      "it per cloud/operation.",
    default = true)

  sealed trait TaskSamplePercent
  case class GlobalTaskSamplePercent(rate: Int) extends TaskSamplePercent
  case class SoakingTaskSamplePercent(rate: Int) extends TaskSamplePercent

  /**
   * (objectStoreProtocol -> Map(operation -> samplePercent)) mapping where Native IO is supported.
   * `samplePercent` is the percentage of tasks that should use native I/O in production.
   *                 This value must be between 0 and 100. For tests, if the value is 0 then
   *                 native I/O is disabled, otherwise it is enabled with 100% sampling rate.
   */
  private final val nativeIOSampleRateMap: Map[ObjectStoreProtocol,
      Map[ObjectStoreOp, TaskSamplePercent]] =
    Map(
      ObjectStoreProtocol.s3 -> Map(
        ObjectStoreOp.read -> GlobalTaskSamplePercent(100),
        ObjectStoreOp.write -> SoakingTaskSamplePercent(100),
        ObjectStoreOp.copy -> GlobalTaskSamplePercent(0),
        ObjectStoreOp.head -> SoakingTaskSamplePercent(100),
        ObjectStoreOp.delete -> GlobalTaskSamplePercent(0),
      ),
      ObjectStoreProtocol.adlgen2 -> Map(
        ObjectStoreOp.read -> GlobalTaskSamplePercent(100),
        ObjectStoreOp.write -> SoakingTaskSamplePercent(100),
        ObjectStoreOp.copy -> GlobalTaskSamplePercent(0),
        ObjectStoreOp.head -> GlobalTaskSamplePercent(0),
        ObjectStoreOp.delete -> GlobalTaskSamplePercent(0),
      ),
      ObjectStoreProtocol.gcs -> Map(
        ObjectStoreOp.read -> GlobalTaskSamplePercent(5),
        ObjectStoreOp.write -> SoakingTaskSamplePercent(100),
        ObjectStoreOp.copy -> GlobalTaskSamplePercent(0),
        ObjectStoreOp.head -> GlobalTaskSamplePercent(0),
        ObjectStoreOp.delete -> GlobalTaskSamplePercent(0),
      )
    )

  val NATIVE_IO_SAMPLE_RATE_MAP =
    new EnumMap(nativeIOSampleRateMap.map {
      case (p, ops) =>
        p -> new EnumMap(ops.map {
          case (op, rate) =>
            val builder =
              buildConf(s"spark.databricks.io.native.${p.name}.${op.name}.taskSamplePercent")
              .internal()
              .doc(s"The sample rate for Native I/O tasks doing ${p.name} ${op.name}" +
                "operation. The sample rate is per task, and the selection is deterministic" +
                "based on taskId and stageId. Sampling is only done on the first attempt of" +
                "a task. This is not done if we are not in task context and for tests.")
              .owner("eng-storage-io")
              .intConf
              .checkValue(v => v >= 0 && v <= 100, "The value must be between 0 and 100.")
            op -> (rate match {
              case GlobalTaskSamplePercent(v) =>
                builder.createWithDefault(v)
              case SoakingTaskSamplePercent(v) =>
                builder.createWithDefaultFunction(() =>
                    if (SQLConf.get.getConf(ACCEPT_SOAKING_FEATURES)) v else 0
                )
            })
        }.asJava)
    }.asJava)

