object PhotonRandomExitTestingStrategy extends Enumeration {
  val ALL, JOIN_AND_UNION_CHILDREN = Value
}

object ABTestingClusterMode extends Enumeration {
  val NONE, LEAD, SHADOW, SHADOW_TEST = Value
}

object ReadAfterWriteMode extends Enumeration {
  val OFF, SHADOW, ON = Value
}

object ServerlessClusterCreatorTag extends Enumeration {
  // For workloads run as part of jobs/notebooks on serverless
  val ComputeGateway = Value
}

/**
 * We'd like to have 3 value property for SystemExpectationOptInType:
 * AUTO, FALSE, TRUE
 .
 * Customer can override the value to TRUE or FALSE.
 *
 * The AUTO mode gives us flexibility to change the default behavior.
 * For the initial release, we will set AUTO as FALSE.
 * But we may change the AUTO behavior to TRUE once we are confident
 * that system expectations does not have any impact on performance
 * or cost.
 */
object SystemExpectationOptInType extends Enumeration {
  val AUTO, FALSE, TRUE = Value
}

/**
 * List of static (immutable during runtime) configs for edge features.
 */
object DatabricksStaticSQLConf extends EdgeFlagSupport {
  override def buildConf(key: String): ConfigBuilder = SQLConf.buildConf(key)

  def buildStaticConf(key: String): ConfigBuilder = SQLConf.buildStaticConf(key)

  def getNativeIONumThreads(conf: SQLConf): Int =
    conf.getConf(DatabricksStaticSQLConf.NATIVE_IO_NUM_THREADS)

  val ACL_PROVIDER =
    buildStaticConf("spark.databricks.acl.provider")
      .internal()
      .doc("Name of the AclProvider. This class is responsible for creating an AclClient. This " +
        "class should implement the com.databricks.sql.acl.AclProvider trait and provide a " +
        "no-args constructor.")
      .stringConf
      .createOptional

  val ACL_CLIENT_BACKEND =
    buildStaticConf("spark.databricks.acl.client")
      .internal()
      .doc("Name of the ACL client backend used by the ReflectionBackedAclClient.")
      .stringConf
      .createOptional

  val ACL_ENABLED =
    buildStaticConf("spark.databricks.acl.enabled")
      .internal()
      .doc("Whether structured data access control is enabled.")
      .fallbackConf(PythonSecurityConf.ENABLE_DF_ACLS)

  val ACL_CHECK_IMPL =
    buildStaticConf("spark.databricks.acl.checkPermission.impl")
      .internal()
      .doc("Permission check rule implementation")
      .stringConf
      .createOptional

  val ACL_CHECK_SKIP_V2_COMMANDS_FOR_TESTING =
    buildStaticConf("spark.databricks.acl.checkPermission.skipV2CommandsForTesting")
      .internal()
      .doc("Skip V2 commands permission check rule for testing.")
      .booleanConf
      .createWithDefault(true)

  val AI_QUERY_DRIVER_PROXY_ENABLED =
    buildStaticConf("spark.databricks.sql.functions.aiFunctions.driverProxy.enabled")
      .internal()
      .doc("When true, ai_query function can query driver proxy api. This feature is currently" +
        "not publicly documented and thus need a feature flag to guard the feature. ")
      .booleanConf
      .createWithDefault(false)

  val AQE_PLAN_VERSIONS_ENABLED =
    buildStaticConf("spark.databricks.sql.aqe.showPlanChangesInUI.enabled")
      .internal()
      .doc("When true, queries in Spark UI will show AQE plan versions.")
      .booleanConf
      // [SC-163252]: Disable AQE plan versions in Spark UI to reduce driver's heap usage.
      .createWithDefault(false)

  val ENFORCE_TABLE_OWNER_ASSIGNMENT =
    buildStaticConf("spark.databricks.acl.enforceTableOwnerAssignment")
      .internal()
      .doc("If true, create and drop table owner even if the table ACL is disabled.")
      .booleanConf
      // We didn't use the `EdgeFlagSupport.edgeFlagForPremiumTiers` because
      // the `EdgeFlagSupport.getConf` has conflicts with `SQLConf.getConf`
      .createWithDefaultFunction(() => DatabricksEdgeConfigs.featureTierAllowsPremiumFeatures(
        if (SparkEnv.get != null) SparkEnv.get.conf else null
      ))

  val HIVE_ACL_CHECK_IMPL =
    buildStaticConf("spark.databricks.hive.acl.checkPermission.impl")
      .internal()
      .doc("Hive permission check rule implementation")
      .stringConf
      .createOptional

  val ACL_FILESYSTEM_CHECK_IMPL =
    buildStaticConf("spark.databricks.acl.filesystem.checkPermission.impl")
      .internal()
      .doc("File system impl check rule implementation")
      .stringConf
      .createOptional

  val HIVE_ACL_FILESYSTEM_CHECK_IMPL =
    buildStaticConf("spark.databricks.hive.acl.filesystem.checkPermission.impl")
      .internal()
      .doc("Hive file system impl check rule implementation")
      .stringConf
      .createOptional

  val SCIM_CLIENT_CLASS =
    buildStaticConf("spark.databricks.acl.scim.client")
      .internal()
      .doc("The full class name of the Databricks SCIM client implementation.")
      .stringConf
      .createWithDefault("com.databricks.sql.acl.PlaceholderScimClient")

  val SQL_ALLOW_SECRETS_EXPRESSION =
    buildStaticConf("spark.databricks.sql.allowSecretsExpression")
      .internal()
      .doc("Whether allow extracting Secrets from Databricks secret service from SQL expression.")
      .booleanConf
      .createWithDefault(true)

  val SQL_ANALYLZE_SECRETS_EXPRESSION_ACCESS =
    buildStaticConf("spark.databricks.sql.analyzeProjectForSecretsExpression")
      .internal()
      .doc("If true, we limit checking the exposure of secrets to expressions that are visible " +
        "to the user (i.e. present in the plan's output).")
      .booleanConf
      .createWithDefault(true)

  val SPARK_SERVER_DBUTILS_BACKED =
    buildConf("spark.databricks.service.dbutils.server.backend")
      .internal()
      .doc("Name of the dbutils backend used by the SparkServerDBUtilsV1Proxy.")
      .stringConf
      .createOptional

  val REPL_DBUTILS_BACKED =
    buildConf("spark.databricks.service.dbutils.repl.backend")
      .internal()
      .doc("Name of the dbutils backend used by the ReplDBUtilsV1Proxy.")
      .stringConf
      .createOptional

  val SQL_ONLY_ACL_ENABLED =
    buildStaticConf("spark.databricks.acl.sqlOnly")
      .internal()
      .doc("Whether SQL-only structured data access control is enabled.")
      .booleanConf
      .createWithDefault(false)

  val SECURE_CATALOG_RESTRICT_OBJ_LISTS =
    buildStaticConf("spark.databricks.acl.secureCatalogRestrictObjLists")
      .internal()
      .doc("Whether database/table/view lists filter based on user's permissions.")
      .booleanConf
      .createWithDefault(true)

  val PYTHON_UDFS_ONLY =
    buildStaticConf("spark.databricks.pyspark.pythonUdfsOnly")
      .doc("If true, allow only Python UDFs to be executed")
      .fallbackConf(PythonSecurityConf.ENABLE_PROCESS_ISOLATION)

  val ISOLATED_PYSPARK_UDF_ENABLED = pysparkSparkIsolationFlag(
    key = "spark.databricks.pyspark.isolatedUDF.enabled",
    doc = "Run pyspark pickled UDF with spark isolation"
  )

  val SPARK_PLAN_GRAPH_NODE_ESCAPE_LABEL_ENABLED =
    buildStaticConf("spark.databricks.sql.ui.sparkPlanGraphNodeEscapeLabel.enabled")
      .internal()
      .doc("Whether or not to escape characters in the label name for SparkPlanGraphNode.")
      .booleanConf
      .createWithDefault(true)

  val DEFAULT_SESSION_CATALOG_ONLY =
    buildStaticConf("spark.databricks.acl.defaultSessionCatalogOnly")
      .internal()
      .doc("If true, allow only default session catalog")
      .fallbackAnyBoolConf(ACL_ENABLED, PythonSecurityConf.ENABLE_CREDENTIAL_PASSTHROUGH)

  val SECURE_DEFAULT_CATALOG_IMPL =
    buildStaticConf("spark.databricks.acl.secureDefaultSessionCatalogImpls")
      .internal()
      .doc(s"Allowed default session catalog implementations when " +
        s"${DEFAULT_SESSION_CATALOG_ONLY.key} is true. Allow multiple values, split by comma")
      .stringConf
      .createWithDefault("com.databricks.sql.transaction.tahoe.catalog.DeltaCatalog")

  val HIVE_NAMESPACE_ONLY =
    buildStaticConf("spark.databricks.acl.hiveNamespaceOnly")
      .internal()
      .doc("If true, when table acl or passthrough is enabled, nested namespace longer " +
        "than 1 would not be supported. This should only be set to false in tests.")
      .booleanConf
      .createWithDefault(true)

  val RESTRICT_XPATH_FUNCTIONS =
    buildConf("spark.databricks.sql.restrictXpathFunctions")
      .internal()
      .doc("If true, we restrict the xpath*() family of functions to not allow file, " +
        "system properties and local network access.")
      .booleanConf
      .createWithDefault(true)

  val DF_ACL_ALLOW_TRANSFORM_USING =
    buildStaticConf("spark.databricks.acl.allowTransformUsing")
      .internal()
      .doc("If true, we allow TRANSFORM() USING syntax to be used. This is insecure, should " +
        "only be used for the period we are rolling it out")
      .booleanConf
      .createWithDefault(false)

  // This is a one off solution for ES-133256, so custom plans can by pass the permission checks
  val SKIP_PERMISSION_PLANS =
    buildStaticConf("spark.databricks.acl.skipCheckingPlans")
      .internal()
      .doc("comma-separated list of class names that would skip the permission checking for table" +
        " acl.")
      .stringConf
      .createWithDefault("")

  val NATIVE_GLOG_VMODULE =
    buildConf("spark.databricks.native.glog.vmodule")
      .internal()
      .doc("Pass to -vmodule for logging (disk-cache=1 enables VLOG(1) logs from disk-cache.cc).")
      .stringConf
      .createWithDefault("")

  val NATIVE_IO_NUM_THREADS =
    buildStaticConf("spark.databricks.io.native.numThreads")
        .internal()
        .doc(
          """
            |Number of I/O threads. The threads are global and alive for the lifetime of the
            |executor.
            |""".stripMargin)
        .intConf
        .checkValue(_ > 0, "number of threads must be greater than 0")
        .createWithDefaultFunction(() => Runtime.getRuntime.availableProcessors())

  val PARQUET_CACHE_MAX_DISK_USAGE =
    buildStaticConf("spark.databricks.io.cache.maxDiskUsage")
    .internal()
    .doc("""
    |Starting value for the size of the disk cache if
    |`sark.databricks.io.cache.guaranteedDiskUtilization` <= 0. In this case, the cache will start
    |with this size but will still autoscale depending on disk usage.
    """.stripMargin)
    .bytesConf(ByteUnit.BYTE)
    .createWithDefaultFunction(() =>
      // Defaulting to 0 is safe as the cache will read the available disk space on initialization.
      InstanceSpecificConf.getMaxDiskCacheSizeInBytes.getOrElse(0)
    )

  val IO_CACHE_TRACEFILE =
    buildConf("spark.databricks.io.cache.tracefile")
      .internal()
      .doc("Enable cache tracing to specified file. HOSTNAME in the filestring is replaced " +
           "by the machine's hostname")
      .stringConf
      .createWithDefault("")

  // see https://docs.google.com/document/d/1ta5AxXCOUA_CXPGgTQfS14y2e201XvRIysmZmwvoqxQ/edit
  val IO_CACHE_MIN_DISK_AVAILABLE =
    buildStaticConf("spark.databricks.io.cache.minDiskAvailable")
      .internal()
      .doc("Minimum number of bytes to remain available on the cache's disks. " +
        "The cache will grow beyond its guaranteed size as long as this value is ensured. ")
      .bytesConf(ByteUnit.BYTE)
      .createWithDefaultFunction(() =>
        if (Utils.isTesting) -1L else (InstanceSpecificConf.getMinTotalFreeSpaceGB() + 10) << 30)

  // Details are present in
  // https://docs.google.com/document/d/1F08srn4ZW6pt8KrjxwdcGrmn_PCE88N23OcaqKHURWo/edit
  val IO_CACHE_BLOCK_SIZE =
    buildConf("spark.databricks.io.cache.block.size")
      .internal()
      .doc(s"If greater than zero enables block cache at the specified block size.")
      .longConf
      .checkValue(_ >= 0, "Block size should not be < 0")
      .createWithDefault(1024 * 1024L)

  val IO_CACHE_GUARANTEED_DISK_UTILIZATION =
    buildStaticConf("spark.databricks.io.cache.guaranteedDiskUtilization")
      .internal()
      .doc("""
             |Cache will use at least this fraction of total disk capacity without checking
             | `spark.databricks.io.cache.minDiskAvailable`.
             |Effective when greater than 0. In that case `spark.databricks.io.cache.maxDiskUsage`
             | is ignored.
             |""".stripMargin)
      .doubleConf
