  object QueuingParsedPlanMLModels {
    // Version 1.1 = proto3, version 1.2 = proto3_mse_medium
    private[sql] val availableTerModelV1MinorVersions: Set[Int] = Set(1, 2)
    val QUEUING_RUNTIME_CLASSIFICATION_MODEL_V1_ENABLED =
      buildConf("spark.databricks.queryRejection.queuingRuntimeClassificationV1.enabled")
        .internal()
        .doc("Whether queuing runtime classification V1 is enabled.")
        .booleanConf
        .createWithDefault(true)

    val QUEUING_TOTAL_EXECUTOR_RUNTIME_MODEL_V1_ENABLED =
      buildConf("spark.databricks.queryRejection.queuingTotalExecutorRuntimePredictorV1.enabled")
        .internal()
        .doc("Whether queuing TotalExecutorRuntime predictor V1 is enabled.")
        .booleanConf
        .createWithDefault(false)

    val QUEUING_TOTAL_EXECUTOR_RUNTIME_MODEL_V1_MINOR_VERSION =
      buildConf(
        "spark.databricks.queryRejection.queuingTotalExecutorRuntimePredictorV1.minorVersion")
        .internal()
        .doc("The minor version number of queuing TotalExecutorRuntime predictor V1.")
        .intConf
        .checkValue(availableTerModelV1MinorVersions.contains,
          f"Invalid minor version number. " +
            f"Available: ${availableTerModelV1MinorVersions.mkString(",")}")
        .createWithDefault(availableTerModelV1MinorVersions.max)

    val QUEUING_PARSED_PLAN_ML_MODEL_PRELOAD_TIMEOUT =
      buildConf("spark.databricks.queryRejection.queuingRuntimeClassification.modelPreloadTimeout")
        .internal()
        .doc("Time out in seconds for pre-loading the ML models.")
        .intConf
        .createWithDefault(10)

    // Minor version of V1.*
    object V1 {
      val QUEUING_RUNTIME_CLASSIFICATION_MODEL_V1_0_ENABLED =
        buildConf("spark.databricks.queryRejection.queuingRuntimeClassificationV1_0.enabled")
          .internal()
          .doc("Whether queuing runtime classification V1.0 is enabled.")
          .booleanConf
          .createWithDefault(true)

      val QUEUING_RUNTIME_CLASSIFICATION_MODEL_V1_0_PROBABILITY_CUTOFF =
        buildConf("spark.databricks.queryRejection.queuingRuntimeClassificationV1_0.probCutOff")
          .internal()
          .doc("The probability cutoff of separating short vs long queries for model version V1.0.")
          .doubleConf
          .createWithDefault(0.6)

      val QUEUING_RUNTIME_CLASSIFICATION_MODEL_V1_1_ENABLED =
        buildConf("spark.databricks.queryRejection.queuingRuntimeClassificationV1_1.enabled")
          .internal()
          .doc("Whether queuing runtime classification V1.1 is enabled.")
          .booleanConf
          .createWithDefault(false)

      val QUEUING_RUNTIME_CLASSIFICATION_MODEL_V1_1_PROBABILITY_CUTOFF =
        buildConf("spark.databricks.queryRejection.queuingRuntimeClassificationV1_1.probCutOff")
          .internal()
          .doc("The probability cutoff of separating short vs long queries for model version V1.1.")
          .doubleConf
          .createWithDefault(0.7)
    }
  }

