    buildConf("spark.databricks.filesystem.clientClassName")
      .doc("Fully qualified class name of file system service client")
      .internal()
      .stringConf
      .createWithDefault(
        "com.databricks.filesystem.FileSystemServiceClientImpl")

  val TEMP_TABLE_MANAGER_CLIENT_CLASS_NAME =
    buildConf("spark.databricks.temptablemanager.clientClassName")
      .doc("Fully qualified class name of temp-table-manager service client")
