      .internal()
      .stringConf
      .createWithDefault(
        "com.databricks.temptablemanager.TempTableManagerClientImpl")

  val STAGING_PRESIGNED_URL_CLIENT_MAX_CONNECTIONS =
    buildConf("spark.sql.staging.presignedUrlClient.maxConnections")
      .doc("The max connection number of the http client used" +
      "within personal staging access command execution")
      .internal()
      .intConf
      .checkValue(v => v > 0, "Needs to be a positive number of max connections.")
      .createWithDefault(64)

  val EXTERNAL_ENGINE_QUERY_MAX_LENGTH =
    buildStaticConf("spark.databricks.external_engine_query_max_length")
        .internal()
        .doc("Maximum length of external engine query being marshalled to DB SQL UI QPL." +
            "This is needed to prevent increase of dropping QPL records.")
        .intConf
        .createWithDefault(6000)

  val STAGING_PRESIGNED_URL_CLIENT_TIMEOUT_IN_SECONDS =
    buildConf("spark.sql.staging.presignedUrlClient.timeout")
      .doc("The timeout in seconds of the http client used" +
      "within personal staging access command execution")
      .internal()
      .intConf
      .checkValue(v => v > 0, "Needs to be a positive number of timeout in seconds.")
      .createWithDefault(120)

  val STAGING_PRESIGNED_URL_CLIENT_MAX_RETRY_NUM =
    buildConf("spark.sql.staging.presignedUrlClient.maxRetryNum")
      .doc("The max retry number of the http client used" +
      "within personal staging access command execution")
      .internal()
      .intConf
      .checkValue(v => v > 0, "Needs to be a positive number of max retry number.")
      .createWithDefault(10)

  val STAGING_PRESIGNED_URL_CLIENT_MAX_RETRY_INTERVAL_MILLIS =
    buildConf("spark.sql.staging.presignedUrlClient.maxRetryInterval")
      .doc("The max retry interval in milliseconds of the http client used" +
      "within personal staging access command execution")
      .internal()
      .longConf
      .checkValue(v => v > 0, "Needs to be a positive number of max retry interval.")
      .createWithDefault(100)

  val REMOTE_HTTP_CLIENT_MAX_CONNECTIONS =
    buildConf("spark.sql.functions.remoteHttpClient.maxConnections")
      .doc("The max connection number of the HTTP client used for remote functions.")
      .internal()
      .intConf
      .checkValue(v => v > 0, "Needs to be a positive number of max connections.")
      .createWithDefault(256)

  val REMOTE_HTTP_CLIENT_TIMEOUT_IN_SECONDS =
    buildConf("spark.sql.functions.remoteHttpClient.timeout")
      .doc("The timeout in seconds of the HTTP client used for remote functions.")
      .internal()
      .intConf
      .checkValue(v => v > 0, "Needs to be a positive number of timeout in seconds.")
      .createWithDefault(360)

  val SPARK_CONNECT_PERSEVE_OPTION_CASING =
    buildStaticConf("spark.connect.perserveOptionCasing")
      .internal()
      .owner("eng-qo-team")
      .doc("When enabled perserves casing for options using data frame reader.")
      .version("3.0.0")
      .booleanConf
      .createWithDefault(false)

  val QUERY_PROFILE_PARAMS_EVENT_ENABLED =
    buildStaticConf("spark.databricks.logging.queryProfile.paramsEventEnabled")
      .internal()
      .doc("If true then the `SparkListenerQueryProfileParamsReady` will be sent for" +
        " QueryProfile building. And the `SparkListenerSQLUsageLogging` event will not be" +
        " sent anymore.")
      .booleanConf
      .createWithDefault(true)

  val ROW_COLUMN_SECURE_VIEW_PLAN_EXPLAIN_ENABLED =
    buildStaticConf("spark.databricks.sql.rowColumnAccess.secureView.explain.enabled")
      .internal()
      .doc(
        "Whether EXPLAIN command output includes subplans of SecureView nodes derived from " +
          "RLS/CM policies; this may be useful for debugging purposes but such subplans are " +
          "excluded from users in general cases in order to hide the filtering logic from " +
          "non-admin consumers of the tables."
      )
      .booleanConf
      .createWithDefault(false)

  val BLOCK_DEPRECATED_FEATURE_ENABLED =
    buildStaticConf("spark.databricks.pyspark.blockDeprecatedFeature.enabled")
      .internal()
      .doc(
        "When set to true, prevents the execution of deprecated PySpark features by " +
          "raising an error. This is useful for enforcing the use of the latest features " +
          "and encouraging migration away from deprecated functionality."
      )
      .booleanConf
      .createWithDefault(false)

  val ARTIFACT_MANAGER_EAGER_INITIALIZATION_FOR_CLONE =
    buildStaticConf("spark.databricks.sql.artifact.eagerInitializationDuringClone")
      .internal()
      .owner("eng-lakestore-safe-spark")
      .doc("If true, artifact manager are initialized eagerly when cloning a Spark session.")
      .booleanConf
      .createWithDefault(DatabricksEdgeConfigs.sharedOrServerlessCluster)

  val ARTIFACT_MANAGER_NFS_ENABLED =
    buildStaticConf("spark.databricks.sql.artifact.nfsEnabled")
      .internal()
      .owner("eng-lakestore-safe-spark")
      .doc("If true, artifacts are written to NFS.")
      .booleanConf
      .createWithDefault(DatabricksEdgeConfigs.sharedOrServerlessCluster)

  val ARTIFACT_MANAGER_NFS_CLONE_ENABLED =
    buildStaticConf("spark.databricks.sql.artifact.nfsCloneEnabled")
      .internal()
      .owner("eng-lakestore-safe-spark")
      .doc("If true, artifacts stored in NFS are copied during session clone." +
        "This is used in streaming queries.")
      .booleanConf
      .createWithDefault(
        // Default off.
        DatabricksEdgeConfigs.sharedOrServerlessCluster && false
      )

  val DRIVER_CAPACITY_CPU_POLLING_INTERVAL_MS =
    buildStaticConf("spark.databricks.sql.drivercapacity.cpuPollingIntervalMs")
      .internal()
      .owner("dbsql-wlm")
      .doc("How often is CPU usage polled on the driver. This will define how " +
        "accurate the driver capacity reactive CPU metric is. The lower the value the more " +
        "accurate the metric is but it will also increase the overhead of polling the CPU. " +
        "Note, this is not used unless DRIVER_CAPACITY_REACTIVE_METRICS_ENABLED is true.")
      .intConf
      .createWithDefault(500)

  val DRIVER_CAPACITY_CPU_WINDOW_MS =
    buildStaticConf("spark.databricks.sql.drivercapacity.cpuWindowMs")
      .internal()
      .owner("dbsql-wlm")
      .doc("The window size in milliseconds to calculate the CPU usage on the " +
        "driver. This will define how fast we react to CPU usage changes, e.g. at 1 second " +
        "window the CPU needs to spike consistently for over a second to trigger a rejection " +
        "based on CPU usage. There is no dependency between this and cpuPollingIntervalMs. " +
        "Note, this is not used unless DRIVER_CAPACITY_REACTIVE_METRICS_ENABLED is true.")
      .intConf
      .createWithDefault(1000)

  val METRIC_STORE_APP_SERVICE_CLIENT_CLASS_NAME =
    buildConf("spark.databricks.sql.functions.metricStoreTVF.appServiceClientClassName")
      .doc("The class name of the actual implementation of MetricStoreAppServiceClient to " +
        "use for the metric_store TVF (internal only).")
      .internal()
      .stringConf
      .createWithDefault("com.databricks.metricstore.MetricStoreAppServiceClientImpl")

  val PYSPARK_DATAFRAME_DEBUGGING_ENABLED =
    buildStaticConf("spark.databricks.pyspark.dataframeDebugging.enabled")
      .internal()
      .doc(
        "When set to true, enables the collection of additional debugging information for " +
          "DataFrame operations in PySpark, providing enhanced traceability and diagnostics."
      )
      .owner("eng-oss-spark")
      .booleanConf
      .createWithDefault(false)

  val UNITY_CATALOG_CUSTOM_RETENTION_ENABLED =
    buildConf("spark.databricks.unityCatalog.customRetention.enabled")
      .doc("Feature flag to enable the RETAIN DROPPED command. When set to true, allow this" +
        " command to run to create and alter catalog and schema-level retention periods." +
        " By default, this flag is set to true."
      )
      .owner("eng-data-gov")
      .booleanConf
      .createWithDefault(true)

  val THRIFT_SERVER_REJECTION_IN_HTTP_RESP =
    buildConf("spark.databricks.thriftserver.rejectionInHttpResp.enabled")
      .doc("Feature flag to allow thriftserver to populate Http response headers with rejection" +
        " reasons."
      )
      .owner("eng-sqlgateway-team")
      .booleanConf
      .createWithDefault(false)

  // Register confs defined in Core's DatabricksSparkConf.PythonSecurity as static SQL confs so they
  // can't be changed via SET. Confs in DatabricksSparkConf.PythonSecurity are not actually
  // registered in SQLConf by SQLConf.register(entry), so they should be only read from SparkConf
  // instead of SQLConf.
  DataSharingConf.configKeys.foreach { conf =>
    SQLConf.registerStaticConfigKey(conf.key)
    SQLConf.register(conf)
  }
  UnityCatalogConf.configKeys.foreach { conf =>
    SQLConf.registerStaticConfigKey(conf.key)
    SQLConf.register(conf)
  }
  PythonSecurityConf.configKeys.foreach { conf =>
    SQLConf.registerStaticConfigKey(conf)
  }
  SecretRedactor.configKeys.foreach { conf =>
    SQLConf.registerStaticConfigKey(conf)
  }
  SafeSparkConf.staticConfigs.foreach { conf =>
    SQLConf.registerStaticConfigKey(conf.key)
    SQLConf.register(conf)
  }
  SafeSparkConf.propagatedFlags.foreach { conf =>
    SQLConf.register(conf)
  }
  SafeSparkConf.sessionConfigs.foreach { conf =>
    SQLConf.register(conf)
  }
}
